  "Ad spend in the period ÷ first purchases in the period. Attributed purchases (AppStack, else Meta) are used when there are any; otherwise every new paid subscription (RevenueCat), Superwall purchases or Mixpanel's purchase event, in that order.": "期間中の広告費 ÷ 期間中の初回購入数。アトリビューションされた購入（AppStack、なければ Meta）があればそれを使い、なければ新規有料サブスクリプション（RevenueCat）、Superwall の購入、Mixpanel の購入イベントの順に使います。",
