  "LTV per paying customer": "有料顧客あたりの LTV",
  "LTV ÷ CAC. CAC is the headline cost per paying customer (or the cost per first purchase when there's no headline). Above 1 a customer earns back what they cost; 3 is the usual healthy mark.": "LTV ÷ CAC。CAC は主要な有料顧客あたりコスト（ない場合は初回購入あたりコスト）。1 を超えれば顧客がコストを回収でき、3 が一般的な健全ラインです。",
  "Blended: ad spend ÷ every new paying customer the source counted, organic included. Real paid CAC is at or above it.": "ブレンド：広告費 ÷ そのソースが数えたすべての新規有料顧客（オーガニックを含む）。実際の有料 CAC はこれ以上になります。",
  "Ad spend ÷ paying customers attributed to the ads.": "広告費 ÷ 広告にアトリビューションされた有料顧客数。",
