  "Plans and price mix": "プランと価格構成",
  "Gross price and share of new paying customers for each plan. Prefilled from RevenueCat's proceeds and new paid subscriptions by product duration, grossed back up by the store fee (an estimate: proceeds also hold renewals).": "各プランの税込価格と新規有料顧客に占める割合。RevenueCat の商品期間別の手取りと新規有料サブスクリプションから、ストア手数料を戻して事前入力（推定値：手取りには更新分も含まれます）。",
