  "Subscribers": "サブスクライバー",
  "Paying subscribers at the end of month 12: every month's new payers, less those who churned or didn't renew (lifetime buyers count as kept).": "12 か月目末の有料サブスクライバー：毎月の新規有料顧客から、解約または更新しなかった人を引いた数（買い切りは継続とみなします）。",
  "Revenue (12 mo)": "売上（12 か月）",
