  "When one month's new payers have earned back that month's ad spend (CAC = CPI ÷ (install to trial × trial to paid)).": "ある月の新規有料顧客が、その月の広告費を回収する時期（CAC = CPI ÷（インストールからトライアル × トライアルから有料））。",
