  "An analysis collects accounts' recent posts and reads what works in them: formats, hooks and what the audience asks for.": "分析では、アカウントの最近の投稿を集め、効いている要素（フォーマット、フック、オーディエンスが求めているもの）を読み解きます。",
  "An analysis is running": "分析を実行中です",
  "Analyses of social posts sit under each app's Research.": "SNS 投稿の分析は、各アプリの「リサーチ」にあります。",
  "Analyses": "分析",
  "App settings": "アプリ設定",
  "Appearance": "外観",
  "Ask the owner to add it in Settings.": "オーナーに「設定」で追加してもらってください。",
  "Back to app": "アプリに戻る",
  "Bring an ad you like, say what to change and add your own pictures: new versions come back in its exact style for {name}. Or describe a shot and make a video.": "気に入った広告を持ち込み、変えたい点を伝えて自分の画像を加えると、同じスタイルのまま {name} 用の新しいバージョンができます。シーンを説明して動画をつくることもできます。",
  "Check the list for {name}": "{name} のリストを確認",
