  "Contact": "お問い合わせ",
  "Cost per install: ad spend divided by installs.": "インストール単価：広告費 ÷ インストール数。",
  "Couldn't load your apps. Reload the page to try again.": "アプリを読み込めませんでした。ページを再読み込みしてもう一度お試しください。",
  "Created in your ad account but switched off: nothing spends until you turn it on in Ads Manager.": "広告アカウントに作成済みですがオフの状態です。広告マネージャでオンにするまで費用はかかりません。",
  "Creatives": "クリエイティブ",
  "Customer acquisition cost: what you spent on ads for each new paying customer.": "顧客獲得単価：新しい有料顧客 1 人あたりにかかった広告費。",
  "Dark": "ダーク",
  "Desktop runner": "デスクトップランナー",
  "Each app keeps its own research, creatives, ads and numbers.": "アプリごとに、リサーチ、クリエイティブ、広告、数値が分かれています。",
  "Every analysis of social posts, for each app and the ones that name none. Each app's own are also under its Research › Social posts.": "SNS 投稿の分析をすべて表示します（アプリごと、およびアプリ未指定のもの）。各アプリの分析は、そのアプリの「リサーチ › SNS 投稿」にもあります。",
  "Every app at once, with its numbers and next step.": "すべてのアプリの数値と次のステップをまとめて表示。",
  "Every app in this workspace: how each one is doing and what to do next.": "このワークスペースのすべてのアプリ：それぞれの状況と次にやること。",
  "Find my competitors": "競合を見つける",
  "Free up space before it fills.": "いっぱいになる前に空き容量を確保しましょう。",
  "Free up space to keep saving ads and creatives.": "広告やクリエイティブを保存し続けるには、空き容量を確保してください。",
  "General & plan": "一般とプラン",
  "Go to": "移動",
  "Guides for each key": "キーごとのガイド",
  "Help": "ヘルプ",
  "Hide {name}'s pages": "{name} のページを隠す",
  "How many months until a customer has paid back what it cost to win them.": "顧客の獲得にかかった費用を、その顧客が何か月で払い戻すか。",
  "How much of your storage is used, by app and by kind, and what to delete to free space.": "ストレージの使用量（アプリ別・種類別）と、空き容量を作るために削除できるもの。",
  "How the app is doing, and the one thing to do next.": "アプリの状況と、次にやるべきこと。",
  "It is set on the server for this workspace.": "このワークスペースではサーバー側で設定されています。",
  "Keyboard shortcuts": "キーボードショートカット",
  "Kind of analysis": "分析の種類",
  "Leave these empty unless you want this app's files in a folder of your own.": "このアプリのファイルを自分のフォルダに置きたい場合以外は、空欄のままにしてください。",
  "Lifetime value divided by acquisition cost. Above 3 is healthy; below 1 loses money on every customer.": "LTV を顧客獲得単価で割った値。3 以上なら健全、1 未満なら顧客 1 人ごとに赤字です。",
  "Lifetime value: what one paying customer pays you over time.": "顧客生涯価値：有料顧客 1 人が長期的に支払ってくれる金額。",
  "Light": "ライト",
  "Main": "メイン",
  "Make your own ads from what works, in your brand.": "効いている広告をもとに、自社ブランドの広告をつくります。",
  "Match the device": "デバイスに合わせる",
  "Match the device's theme": "デバイスのテーマに合わせる",
  "Members": "メンバー",
  "Menu": "メニュー",
  "Menus, pages and messages. Your competitors' ads and your own copy stay in the language they were written in.": "メニュー、ページ、メッセージの言語です。競合の広告や自社のコピーは、書かれた言語のまま表示されます。",
