  "Start with your competitors: the analysis finds them from your app's profile and reads what wins for them on each channel.": "まずは競合から。分析はアプリのプロフィールから競合を見つけ、各チャネルで何が当たっているかを読み解きます。",
  "Step by step: where to find each key and ID, and what it costs. Add them under Settings › Your keys.": "ステップごとに、各キーと ID の見つけ方と費用を説明します。追加は「設定 › あなたのキー」から。",
  "Storage is almost full": "ストレージがほぼいっぱいです",
