  "Storage {percent} full": "ストレージ使用率 {percent}",
  "Stuck, or something looks wrong? Write to us and say what you were doing.": "行き詰まったときや、おかしな点があるときは、何をしていたかを添えてご連絡ください。",
  "Templates": "テンプレート",
  "The accounts {name}'s pages work from: Meta for ads, and RevenueCat, Superwall, Mixpanel or AppStack for what customers earn.": "{name} のページが使うアカウント：広告には Meta、顧客の売上には RevenueCat・Superwall・Mixpanel・AppStack。",
  "The ads, apps and posts that work for your competitors.": "競合で効いている広告、アプリ、投稿。",
