  "The last step stopped": "最後のステップで止まりました",
  "The part of a Meta campaign that holds the budget, audience and placements; its ads sit inside it.": "Meta キャンペーンのうち、予算・オーディエンス・配置を持つ階層。広告はその中に入ります。",
  "The services this workspace uses. Each key is checked when you save it and kept in your own Supabase project.": "このワークスペースで使うサービスです。各キーは保存時に確認され、あなた自身の Supabase プロジェクトに保管されます。",
  "The steps to set up your app, one at a time.": "アプリを設定する手順を 1 つずつ。",
