  "Their ads": "競合の広告",
  "This workspace's name, your plan and how much of it is used.": "このワークスペースの名前、プラン、その使用量。",
  "Turn a brief, a winning format or a competitor's ad into videos and image ads. Each one is checked against your brand's rules, and only the ones you approve can launch. {n} approved so far.": "ブリーフ、当たっているフォーマット、競合の広告を、動画広告や画像広告に変えます。それぞれブランドのルールでチェックされ、承認したものだけが出稿できます。これまでに {n} 件承認済み。",
  "Updates": "アップデート",
  "Use the dark theme": "ダークテーマを使う",
  "Use the light theme": "ライトテーマを使う",
  "What each page does": "各ページでできること",
