  "What every creative for {name} follows, and the pictures it uses. The essentials are here; the rest is under More detail.": "{name} のすべてのクリエイティブが従うルールと、使う画像。基本はここにあり、残りは「詳細」にあります。",
  "What works in competitors' and creators' own posts on Instagram, TikTok and YouTube: formats, hooks and what their audience asks for. Every run is kept.": "競合やクリエイターが Instagram・TikTok・YouTube で投稿している内容のうち、効いているもの（フォーマット、フック、オーディエンスが求めていること）。実行結果はすべて保存されます。",
  "What your ads cost next to what customers pay you.": "広告費と、顧客が支払ってくれる金額を並べて比較します。",
  "What {name} is and who it's for: your profile, and the AI's fuller read of your links.": "{name} とは何で、誰のためのものか。あなたのプロフィールと、リンクをもとにした AI の詳しい分析。",
  "Where files go": "ファイルの保存先",
