  "Approved creatives arrive in your own Meta ad account as {paused} ads, in a campaign and an {adSet}. Nothing spends until you switch them on in Ads Manager.": "承認したクリエイティブは、キャンペーンと{adSet}に入った{paused}の広告として、あなたの Meta 広告アカウントに届きます。広告マネージャでオンにするまで費用はかかりません。",
