  "payback": "回収期間",
  "{n} template for this app. Open it, add your words and pictures, and it's made in this style.": "このアプリのテンプレートは {n} 件です。開いて言葉と画像を加えると、このスタイルで作られます。",
  "{n} templates for this app. Open one, add your words and pictures, and it's made in that style.": "このアプリのテンプレートは {n} 件です。1 つ開いて言葉と画像を加えると、そのスタイルで作られます。",
