  "App stores shows your competitors' apps on the App Store: ratings, prices, updates and what their reviewers love and hate.": "アプリストアでは、App Store 上の競合アプリを表示します：評価、価格、アップデート、レビューで好まれている点と不満点。",

  // F5 Platform
  "See what's working for your competitors": "競合で成果が出ているものを見つける",
  "Track your competitors, see which ads and posts are working for them, and turn what you learn into your own creatives.": "競合を追跡し、成果の出ている広告や投稿を見極め、学んだことを自社のクリエイティブに活かします。",
