  "The ads run from this Page.": "広告はこのページから配信されます。",
  "Pick…": "選択…",
  "Instagram account": "Instagram アカウント",
  "Instagram placements show this account.": "Instagram の配置ではこのアカウントが表示されます。",
  "Without one, the ads don't run on Instagram.": "設定しない場合、広告は Instagram に配信されません。",
  "None (Facebook only)": "なし（Facebook のみ）",
  "@{username} (from the Page)": "@{username}（ページから）",
  "Primary text": "メインテキスト",
  "({count}/125 before “more”; Reels show about 40)": "（「もっと見る」まで {count}/125、リールは約 40 文字）",
  "Headline": "見出し",
  "Button": "ボタン",
  "Only the buttons this campaign's objective allows.": "このキャンペーンの目的で使えるボタンのみ表示されます。",
  "Link": "リンク",
  "The App Store page.": "App Store のページです。",
  "Where the button sends people.": "ボタンを押した人の移動先です。",
  "Description": "説明",
  "Where disclaimers go (from the creative's copy). Instagram and single-media Facebook Feed ads don't show it.": "免責事項を入れる場所です（クリエイティブのコピーから）。Instagram と単一メディアの Facebook フィード広告には表示されません。",
  "Made with AI?": "AI で作成しましたか？",
  "Meta asks advertisers to say whether the media was made or edited with AI; it may then show an “AI info” label where the law asks for it (the EU, India, Taiwan, California, New York).": "Meta は、メディアが AI で作成・編集されたかどうかの申告を広告主に求めています。法律で必要な地域（EU、インド、台湾、カリフォルニア州、ニューヨーク州）では「AI 情報」ラベルが表示されることがあります。",
  "Yes, made or edited with AI": "はい、AI で作成・編集しました",
  "Preselected: a picked creative was made by a model (AI people or a generated scene).": "あらかじめ選択済み：選んだクリエイティブにモデルで作られたもの（AI の人物や生成されたシーン）があります。",
  "Creatives made in the Studio are AI-generated, so this is usually the answer.": "Studio で作ったクリエイティブは AI 生成なので、通常はこちらです。",
  "No AI in this media": "このメディアに AI は使っていません",
  "Display link": "表示リンク",
  "A short domain shown on the ad, like acme.app. Not the destination.": "広告に表示される短いドメイン（例：acme.app）。リンク先ではありません。",
  "URL parameters": "URL パラメータ",
  "Advantage+ creative": "Advantage+ クリエイティブ",
  "Lets Meta touch up the media and rewrite text per person (brightness, animation, text variations). Off keeps each ad exactly as approved.": "Meta が人ごとにメディアを補正し、テキストを書き換えます（明るさ、アニメーション、テキストのバリエーション）。オフにすると、各広告は承認したとおりのままです。",
  "Optional tags added to the link.": "リンクに付ける任意のタグです。",
  "Empty: Launch adds UTM tags with the campaign, ad set and ad names, so analytics see the naming convention.": "空欄の場合：出稿がキャンペーン・広告セット・広告の名前で UTM タグを付けるので、分析ツールでも命名規則がわかります。",
  "Everywhere else (fallback)": "その他すべて（フォールバック）",
  "Feeds (4:5 or 1:1)": "フィード（4:5 または 1:1）",
  "Stories and Reels (9:16)": "ストーリーズとリール（9:16）",
  "{n} picked": "{n} 件選択中",
  "Pixel from Launch settings": "出稿設定のピクセル",
  "Follows the naming convention; it updates with the places you pick unless you rename it.": "命名規則に沿っています。名前を変更しない限り、選んだ地域に合わせて更新されます。",
  "Optimise for": "最適化の対象",
  "{name} (default)": "{name}（デフォルト）",
  "The playbook: optimise for the deepest event that still happens often (a trial or purchase over an install), so Meta learns who pays.": "プレイブックの方針：十分な頻度で起きる、できるだけ深いイベントで最適化します（インストールよりトライアルや購入）。そうすると Meta が課金する人を学習します。",
  "Meta app {id}": "Meta アプリ {id}",
  "Add the Meta app id in Launch settings.": "出稿設定で Meta アプリ ID を追加してください。",
  "App event": "アプリイベント",
  "Sent by the Meta SDK (or your MMP) from the app.": "アプリ内の Meta SDK（または MMP）から送信されます。",
  "Pixel": "ピクセル",
  "The website's Meta pixel (or dataset).": "ウェブサイトの Meta ピクセル（またはデータセット）です。",
  "Connect a pixel in Launch settings: this goal needs one.": "出稿設定でピクセルを接続してください。この目標にはピクセルが必要です。",
  "Custom conversions": "カスタムコンバージョン",
  "Event": "イベント",
  "Send people to": "誘導先",
  "Budget": "予算",
  "This campaign gives each ad set its own budget (ABO).": "このキャンペーンでは広告セットごとに予算を設定します（ABO）。",
  "Lifetime budget": "通算予算",
  "Testing: about $20–50 a day per ad set, with about 5 ads in it.": "テスト：広告セットごとに 1 日あたり約 $20〜50、広告は約 5 件。",
  "Raise winners about 20% every 48 h.": "勝ちパターンは 48 時間ごとに約 20% ずつ増額します。",
  "Budget type": "予算の種類",
  "Daily": "1 日",
  "Ad set budget": "広告セットの予算",
  "Ends": "終了",
  "A lifetime budget needs an end date.": "通算予算には終了日が必要です。",
  "The campaign holds the budget and the bid strategy (CBO), so this ad set has none of its own.": "予算と入札戦略はキャンペーン側にある（CBO）ため、この広告セット自体にはありません。",
  "Who sees the ads": "広告を見る人",
  "Broad targeting usually wins: the creative tells Meta who it's for.": "通常は幅広いターゲティングが有利です。誰向けかはクリエイティブが Meta に伝えます。",
