  "Add a country, region or city": "国・地域・都市を追加",
  "Advantage+ audience": "Advantage+ オーディエンス",
  "On: the ages and interests below are suggestions. Meta may show the ads to people outside them when it expects better results.": "オン：下の年齢と興味関心は提案扱いです。より良い成果が見込めるときは、Meta がその範囲外の人にも広告を表示することがあります。",
  "Off: the ages and interests below are hard limits.": "オフ：下の年齢と興味関心は厳密な条件になります。",
  "Youngest": "最低年齢",
  "Oldest": "最高年齢",
