  "Men": "男性",
  "Women": "女性",
  "Interests": "興味・関心",
  "Optional. Only from Meta's search, so every interest is real. Most tests run without any.": "任意。Meta の検索結果からのみ選べるので、どれも実在する興味関心です。ほとんどのテストは指定なしで実施します。",
  "Search interests (fitness, cooking…)": "興味・関心を検索（フィットネス、料理…）",
  "Estimating the audience…": "オーディエンスを推定中…",
  "About {low}–{high} people a month (Meta's estimate).": "月に約 {low}〜{high} 人（Meta の推定）。",
  "Meta's audience estimate shows here.": "Meta のオーディエンス推定がここに表示されます。",
  "Where the ads show": "広告の表示場所",
  "Advantage+ placements": "Advantage+ 配置",
  "Pick placements": "配置を選ぶ",
  "Meta shows the ads wherever they'll do best: Feeds, Stories, Reels and more. Recommended.": "Meta が成果の出やすい場所に広告を表示します：フィード、ストーリーズ、リールなど。おすすめです。",
  "Only where you pick. Fewer places usually costs more per result.": "選んだ場所にのみ表示します。場所が少ないほど、結果あたりの費用は通常高くなります。",
  "EU transparency (Digital Services Act)": "EU の透明性（デジタルサービス法）",
  "Ads shown in the EU name who benefits from them and who pays for them.": "EU で表示される広告には、受益者と支払者を明記します。",
  "Who benefits": "受益者",
  "Who pays": "支払者",
  "Usually the website.": "通常はウェブサイトです。",
  "Not set": "未設定",
  "Pay for": "課金対象",
