  "Minimum ROAS": "最低 ROAS",
  "Return per unit spent, e.g. 1.5 = 150%. Needs the Conversion value goal.": "消化額あたりのリターン（例：1.5 = 150%）。「コンバージョン値」の目標が必要です。",
  "Starts": "開始",
