  "Empty: runs until you stop it.": "空欄の場合：停止するまで配信します。",
  "Weekly schedule (day-parting)": "週間スケジュール（時間帯指定）",
  "Show the ads only on these days and hours (the account's time zone).": "この曜日と時間帯にのみ広告を表示します（アカウントのタイムゾーン）。",
  "Only with a lifetime budget.": "通算予算の場合のみ。",
