  "Days": "日数",
  "Attribution window": "アトリビューション期間",
  "How long after a click or view a result counts. Meta's default (7-day click, 1-day view) suits most accounts.": "クリックや表示のあと、どれくらいの期間の結果を計測するかです。Meta のデフォルト（クリック後 7 日、表示後 1 日）がほとんどのアカウントに合います。",
  "Meta’s default (7-day click, 1-day view)": "Meta のデフォルト（クリック後 7 日、表示後 1 日）",
