  "Custom audiences": "カスタムオーディエンス",
  "People from your website, app or a lookalike. With Advantage+ audience on, these are suggestions too.": "ウェブサイトやアプリ、類似オーディエンスの人です。Advantage+ オーディエンスがオンの場合、これらも提案扱いになります。",
  "Include an audience…": "オーディエンスを含める…",
