  "miles": "マイル",
  "km": "km",
  "Languages": "言語",
  "Only people who use Facebook or Instagram in these languages. Usually left empty.": "これらの言語で Facebook や Instagram を使っている人のみ。通常は空欄のままにします。",
  "Add a language": "言語を追加",
  "Targeting an EU country adds the Digital Services Act fields (who benefits, who pays).": "EU の国をターゲットにすると、デジタルサービス法の項目（受益者、支払者）が追加されます。",
  "This campaign has a special ad category: targeting must stay 18–65, all genders.": "このキャンペーンには特別な広告カテゴリがあります。ターゲティングは 18〜65 歳、すべての性別のままにする必要があります。",
