  "Page likes": "ページへの「いいね！」",
  "Post engagement": "投稿のエンゲージメント",
  "App installs": "アプリのインストール",
  "Follows the naming convention so Measure can group results; change it if you like.": "測定で結果をグループ化できるよう、命名規則に沿っています。必要なら変更できます。",
  "Objective": "目的",
  "Where the money is set decides who moves it between ad sets.": "予算をどこに設定するかで、広告セット間で誰が予算を動かすかが決まります。",
  "On each ad set (ABO)": "広告セットごと（ABO）",
  "You give every ad set its own budget, so each new concept gets a fair test. The playbook's choice for testing.": "広告セットごとに予算を設定するので、新しいコンセプトをそれぞれ公平にテストできます。プレイブックでのテスト向けの選択です。",
  "On the campaign (CBO)": "キャンペーン（CBO）",
  "One budget; Meta moves it to the ad sets doing best. The playbook's choice for scaling winners.": "予算は 1 つで、Meta が成果の良い広告セットに配分します。プレイブックでの勝ちパターンのスケーリング向けの選択です。",
  "Testing usually runs ABO, so every concept gets spend. CBO is for scaling proven winners.": "テストは通常 ABO で行い、すべてのコンセプトに予算が使われるようにします。CBO は実績のある勝ちパターンのスケーリング用です。",
  "Spent over the campaign's dates; needs an end date.": "キャンペーン期間中に消化します。終了日が必要です。",
  "Meta may spend a little more on good days and less on others.": "Meta は成果の良い日に少し多く、ほかの日に少なく消化することがあります。",
  "Campaign budget": "キャンペーンの予算",
  "Meta asks for the cap or ROAS floor on each ad set of a CBO campaign; set those in Ads Manager before publishing.": "CBO キャンペーンでは、Meta が各広告セットに上限額や最低 ROAS を求めます。公開前に広告マネージャで設定してください。",
  "A lifetime budget needs an end date (More options).": "通算予算には終了日が必要です（その他のオプション）。",
  "Spending limit": "消化上限",
  "The most this campaign may ever spend, whatever the budgets say. Optional.": "予算の設定にかかわらず、このキャンペーンが消化できる最大額です。任意。",
  "No limit": "上限なし",
  "Special ad category": "特別な広告カテゴリ",
  "Only for ads about housing, jobs, credit or politics: Meta then limits targeting by age, gender and place.": "住宅・雇用・クレジット・政治に関する広告のみ。その場合、Meta は年齢・性別・地域によるターゲティングを制限します。",
  "None": "なし",
  "Countries for the category": "カテゴリの対象国",
  "Two-letter codes, comma separated (US, GB).": "2 文字のコードをカンマ区切りで（US, GB）。",
  "SKAdNetwork attribution": "SKAdNetwork アトリビューション",
  "Apple’s privacy-safe install counting for iOS apps. Leave on for iOS.": "iOS アプリ向けの、Apple によるプライバシーに配慮したインストール計測です。iOS ではオンのままにしてください。",
  "Housing": "住宅",
