  "A new campaign and ad set": "新しいキャンペーンと広告セット",
  "Testing: one ABO campaign, about $20–50 a day per ad set. Scaling: one CBO campaign for proven winners.": "テスト：ABO キャンペーン 1 つ、広告セットごとに 1 日約 $20〜50。スケーリング：実績のある勝ちパターン用の CBO キャンペーン 1 つ。",
  "Stage": "ステージ",
  "Names say TEST so Measure can group results (new concepts at a small budget).": "名前に TEST が入るので、測定で結果をグループ化できます（少額予算で新しいコンセプトを試す段階）。",
  "Names say SCALE so Measure can group results (winners moved up).": "名前に SCALE が入るので、測定で結果をグループ化できます（勝ちパターンを昇格した段階）。",
