  "optional": "任意",
  "no spend in 28 days": "28 日間消化なし",
  "day {day} of {min}–{max}": "{min}〜{max} 日中 {day} 日目",
  "Meta knows nothing about a fresh account. A few days of healthy engagement first gives conversion ads a cleaner start (fewer rejections, steadier delivery). It won't make a weak ad profitable; it just starts on the right foot.": "Meta は新しいアカウントについて何も知りません。まず数日間、健全なエンゲージメントを積むと、コンバージョン広告をきれいに始められます（不承認が減り、配信が安定）。弱い広告が儲かるようになるわけではありませんが、良いスタートを切れます。",
  "Create an {engagement} campaign in Ads Manager. Sell nothing.": "広告マネージャで{engagement}キャンペーンを作成します。何も販売しません。",
  "Engagement": "エンゲージメント",
  "Use simple static images people like to react to (puppies, babies). A small budget is plenty: about $37 bought ~2,400 engagements at $0.02 in the playbook's example.": "反応してもらいやすいシンプルな静止画（子犬、赤ちゃん）を使います。少額の予算で十分です。プレイブックの例では、約 $37 で約 2,400 件のエンゲージメントを 1 件 $0.02 で獲得しました。",
  "Let it run {min}–{max} days. Avoid switching things on and off or big edits meanwhile.": "{min}〜{max} 日間配信します。その間は、オン・オフの切り替えや大きな編集は避けてください。",
  "Then publish the app drafts from Launch and optimise for the conversion you care about.": "その後、出稿で作ったアプリの下書きを公開し、重視するコンバージョンに最適化します。",
  "I've started the warm-up": "ウォームアップを開始しました",
  "Mark warmed up": "ウォームアップ完了にする",
  "Open Ads Manager ↗": "広告マネージャを開く ↗",
  "Skip, the account has history": "スキップ（アカウントに実績あり）",
  "Attribution: SDK first, MMP later": "アトリビューション：まず SDK、あとで MMP",
  "Not SDK or MMP: the SDK gets campaigns learning now; the MMP gives better attribution once it has data. Starting on the MMP from day one usually starves learning.": "SDK か MMP かの二択ではありません。SDK でキャンペーンの学習を今すぐ始め、データがたまったら MMP でより正確なアトリビューションを得ます。初日から MMP だけで始めると、たいてい学習に必要なデータが不足します。",
  "AppStack connected": "AppStack 接続済み",
  "no MMP connected": "MMP 未接続",
  "{n} {events} in 7 days": "7 日間で{events} {n} 件",
  "About 50 a week is enough.": "週に約 50 件あれば十分です。",
  "I'm here": "今ここ",
  "You have enough volume to move the optimisation events to the MMP.": "最適化イベントを MMP に移すのに十分な件数があります。",
  "Advice for the scaling ad set from the playbook. Budgets are changed by you in Ads Manager; nothing here changes them.": "プレイブックにもとづく、スケーリング用広告セットへのアドバイスです。予算は広告マネージャでご自身で変更します。ここでは何も変更しません。",
  "Last 3 days": "直近 3 日間",
