  "Cost per {event}, last 3 days": "{event}単価（直近 3 日間）",
  "The 4 days before": "その前の 4 日間",
  "About 20% every 48 hours while it holds; judge where the cost settles, not the next morning.": "成果が保たれている間は 48 時間ごとに約 20%。翌朝の数字ではなく、コストが落ち着く水準で判断します。",
  "Open the scaling ad set ↗": "スケーリング用の広告セットを開く ↗",
  "Playbook": "プレイブック",
  "Suggestions from the Meta ads playbook. Optional: skip or mark anything done.": "Meta 広告プレイブックからの提案です。任意なので、スキップしたり完了にしたりできます。",
  "Meta SDK with your key events": "主要イベント付きの Meta SDK",
  "Install, trial start and purchase sent from the app through Meta's SDK (or Pixel + Conversions API on the web). Run SDK-optimised campaigns straight away.": "インストール、トライアル開始、購入を Meta の SDK（ウェブでは Pixel + Conversions API）でアプリから送ります。SDK で最適化したキャンペーンをすぐに配信できます。",
  "MMP collecting alongside": "並行して MMP がデータを収集",
  "Connect the MMP (AppStack here) while the SDK campaigns run, so it builds conversion history.": "SDK のキャンペーンを配信している間に MMP（ここでは AppStack）を接続し、コンバージョン履歴をためます。",
  "Switch events to the MMP": "イベントを MMP に切り替え",
  "Once the MMP has enough conversions, set the app's events to come from it in Ads Manager (the app's integrations) and optimise on them.": "MMP に十分なコンバージョンがたまったら、広告マネージャ（アプリの連携設定）でイベントの送信元を MMP にし、そのイベントで最適化します。",
