  "Ad set budget (ABO)": "広告セット予算（ABO）",
  "You control each ad set's spend. Testing always uses this.": "広告セットごとの消化金額を自分で管理します。テストでは常にこちらを使います。",
  "Works from day one; finds people who install.": "初日から使えます。インストールする人を見つけます。",
  "Finds people who start a trial. Needs the StartTrial event from the SDK or MMP.": "トライアルを始める人を見つけます。SDK か MMP からの StartTrial イベントが必要です。",
  "Finds people who pay. Needs the Purchase event; use once it fires often.": "支払う人を見つけます。Purchase イベントが必要です。頻繁に発生するようになってから使ってください。",
  "Launch settings": "出稿の設定",
  "Where ads go, the testing and scaling ad sets, the promotion rules and daily uploads.": "広告の送り先、テスト用とスケーリング用の広告セット、昇格ルール、毎日アップロード。",
