  "Phone calls to your business.": "ビジネスへの電話。",
  "Reminders": "リマインダー",
  "People setting a reminder for an event.": "イベントのリマインダーを設定する人。",
  "Event responses": "イベントへの返信",
  "RSVPs to a Facebook event.": "Facebook イベントへの参加の返信。",
  "Follows of your Facebook Page.": "Facebook ページのフォロー。",
  "Leads (instant form)": "リード（インスタントフォーム）",
  "A form inside Facebook or Instagram.": "Facebook や Instagram 内のフォーム。",
  "Conversion leads": "コンバージョンリード",
  "Leads likely to become customers.": "顧客になりそうなリード。",
  "Conversion value": "コンバージョン値",
  "The highest purchase value (ROAS).": "最も高い購入金額（ROAS）。",
  "Installs of the app.": "アプリのインストール。",
  "Highest volume": "最大数量",
  "Meta gets as many results as the budget allows. The playbook's default.": "Meta が予算内でできるだけ多くの成果を獲得します。プレイブックのデフォルトです。",
  "Keeps the average cost per result near an amount you set.": "平均の結果単価を、設定した金額付近に保ちます。",
  "Never bids more than an amount you set in any auction.": "どのオークションでも、設定した金額を超えて入札しません。",
  "ROAS goal": "ROAS の目標",
  "Keeps return on ad spend above a floor (needs purchase values).": "広告費用対効果を下限以上に保ちます（購入金額が必要）。",
