  "Don't": "NG",
  "Fill in the fields below, or import a brand guide you already have (paste it, or pick a file). Until then, creatives use what's below and the AI product profile.": "下の項目を入力するか、お手持ちのブランドガイドをインポートしてください（貼り付けるか、ファイルを選択）。それまでは、下の内容と AI の商品プロフィールをもとにクリエイティブを作ります。",
  "It didn't upload.": "アップロードされませんでした。",
  "It's removed from this product and its file is deleted. This can't be undone.": "この商品から外され、ファイルも削除されます。元に戻せません。",
  "It's removed from this product. To keep it but leave it out of suggestions, hide it instead.": "この商品から外されます。残したまま候補に出したくない場合は、代わりに非表示にしてください。",
  "Kind picked by you: the AI won't change it": "種類はあなたが選択済み：AI は変更しません",
  "OpenAI didn't answer. Try again.": "OpenAI から応答がありませんでした。もう一度お試しください。",
  "Optional. Names, @handles or links, separated by commas. Don't know any yet? That's what {app} is for: leave it empty.": "任意です。名前、@ハンドル、リンクをカンマ区切りで入力してください。まだわからなくても大丈夫。それを見つけるのが {app} の役目なので、空欄のままでかまいません。",
  "QA checks {n} forbidden claim, plus the AI profile's claims to avoid.": "QA では {n} 件の禁止表現と、AI プロフィールにある避けるべき表現をチェックします。",
  "QA checks {n} forbidden claims, plus the AI profile's claims to avoid.": "QA では {n} 件の禁止表現と、AI プロフィールにある避けるべき表現をチェックします。",
  "Store listing, docs, anything about it. One per line. After you save, the AI reads them and your website's pages, then offers a fuller profile: the problem, the customer, your brand colours and voice.": "ストアページ、ドキュメントなど、関係するものなら何でも。1 行に 1 つ入力してください。保存すると AI がそれらとサイトのページを読み、課題、顧客、ブランドカラー、トーンまで含んだ詳しいプロフィールを提案します。",
  "Suggestions for colours, voice and claims to avoid come from the AI's read of your links. It needs {keys}.": "カラー、トーン、避けるべき表現の提案は、AI がリンクを読んだ結果から作られます。必要なもの：{keys}。",
  "That file isn't in this product's folder.": "このファイルはこの商品のフォルダにありません。",
  "The AI reads your link and your website's pages, then writes a fuller profile: the problem, the customer, value, pricing, proof, your brand colours and voice.": "AI がリンクとサイトのページを読み、課題、顧客、価値、価格、裏づけ、ブランドカラーとトーンまで含んだ詳しいプロフィールを書きます。",
  "The AI reads your {n} links and your website's pages, then writes a fuller profile: the problem, the customer, value, pricing, proof, your brand colours and voice.": "AI が {n} 件のリンクとサイトのページを読み、課題、顧客、価値、価格、裏づけ、ブランドカラーとトーンまで含んだ詳しいプロフィールを書きます。",
  "The app couldn't be deleted: {reason}. Try again in a moment.": "アプリを削除できませんでした：{reason}。しばらくしてからもう一度お試しください。",
  "The app's files couldn't be removed, so the app wasn't deleted. {reason}": "アプリのファイルを削除できなかったため、アプリは削除されていません。{reason}",
  "The change wasn't saved.": "変更は保存されませんでした。",
  "The cut-out wasn't queued.": "切り抜きはキューに追加されませんでした。",
  "The image was uploaded but couldn't be saved. Try again.": "画像はアップロードされましたが、保存できませんでした。もう一度お試しください。",
  "The numbers a creative may show (a rating, a count, a comparison price), word for word. QA fails any other number that isn't an offer's wording.": "クリエイティブに表示してよい数字（評価、件数、比較価格）を一字一句そのまま。オファーの文言以外の数字があると QA で不合格になります。",
  "There's no AI profile yet: read your links first.": "まだ AI プロフィールがありません。先にリンクを読み込んでください。",
  "These fields get the AI profile's version. You can undo it afterwards.": "これらの項目が AI プロフィールの内容に置き換わります。あとで元に戻せます。",
  "They didn't agree: don't use them.": "同意を得ていません。使用しないでください。",
  "This app doesn't exist (it may have been deleted already).": "このアプリは存在しません（すでに削除された可能性があります）。",
  "This app doesn't exist.": "このアプリは存在しません。",
  "This is the product's one competitor list, the same one as Research → Competitors. Ones you follow there or that have a Facebook Page are removed there.": "これは商品共通の競合リストで、「リサーチ → 競合」と同じものです。そこでフォロー中の競合や Facebook ページがある競合は、そちらで削除してください。",
  "Use a TTF, OTF or WOFF font file (WOFF2 can't be rendered).": "TTF、OTF、WOFF のフォントファイルを使ってください（WOFF2 は描画できません）。",
  "We don't offer": "提供していないもの",
  "We've filled in what we could from your description; fix anything that's off.": "説明から読み取れる内容を入力しました。違うところがあれば直してください。",
  "What Meta's link description carries on every ad (written copy starts with these). Keep results disclaimers here, not on the image.": "すべての広告で Meta のリンク説明に入る内容です（広告文はここから始まります）。効果に関する注意書きは画像ではなくここに入れてください。",
  "What it is, who it's for and how people buy it, in a few honest lines.": "それが何か、誰のためのものか、どう買われるかを、正直に数行で。",
  "What you sell, as pictures. They are suggested as references when you recreate a competitor's ad.": "販売しているものを画像で。競合の広告を作り直すときに、参考画像として提案されます。",
  "What you're building": "つくっているもの",
  "What's never offered, and how offers may be stacked and framed.": "提供しないもの、オファーの組み合わせ方と見せ方。",
  "Who it's for": "誰のためのものか",
