  "The AI looks at {n} image again and relabels, regroups and re-tags it. Kinds you picked stay as they are. It takes a minute or two.": "AI が {n} 枚の画像を見直し、ラベル、グループ、タグを付け直します。選んだ種類はそのままです。1～2 分かかります。",
  "The app": "アプリ",
  "The basics": "基本情報",
  "The brand holds {n} screenshots. Remove some first.": "ブランドに保存できるスクリーンショットは {n} 枚までです。先にいくつか削除してください。",
  "The busy parent, 30–45": "忙しい親、30～45 歳",
  "The closed list: no creative may show any other price, discount, trial or code, and QA fails one that does.": "限定リストです。ほかの価格、割引、トライアル、コードはクリエイティブに表示できず、表示すると QA で不合格になります。",
  "The cut-out failed.": "切り抜きに失敗しました。",
  "The cut-out failed: {error}": "切り抜きに失敗しました：{error}",
  "The cut-out: open the transparent PNG": "切り抜き：透過 PNG を開く",
  "The desktop runner removes the background and saves a transparent PNG of this image (about {credits} Higgsfield credit). Composed ads can then place your real product instead of the model drawing it. The new one replaces the current cut-out.": "デスクトップランナーが背景を削除し、この画像の透過 PNG を保存します（Higgsfield のクレジット約 {credits}）。組版広告では、モデルに描かせる代わりに実際の商品を配置できます。新しい切り抜きは現在のものと置き換わります。",
  "The desktop runner removes the background and saves a transparent PNG of this image (about {credits} Higgsfield credit). Composed ads can then place your real product instead of the model drawing it.": "デスクトップランナーが背景を削除し、この画像の透過 PNG を保存します（Higgsfield のクレジット約 {credits}）。組版広告では、モデルに描かせる代わりに実際の商品を配置できます。",
  "The last read stopped before it finished.": "前回の読み込みは完了前に止まりました。",
  "The people ads speak to. Variant 1 speaks to the first, variant 2 to the second, and so on.": "広告が語りかける相手です。バリエーション 1 は 1 人目、バリエーション 2 は 2 人目に、という順で語りかけます。",
  "The rewrite broke your brand rules ({problems}), so your prompt was kept.": "書き直した結果がブランドのルールに反していたため（{problems}）、元のプロンプトのままにしました。",
  "The {n} image is hidden.": "{n} 枚の画像は非表示です。",
