  "{n}/{max} with files": "ファイルあり {n}/{max}",
  "A clean copy of the ad's layout with its brand, product, people and words taken out, saved to this product's Library.": "広告のレイアウトから、ブランド・商品・人物・文字を取り除いたクリーンなコピーです。この商品のテンプレートライブラリに保存されます。",
  "A product's library holds up to {n} of your own templates. Remove one first.": "1 つの商品のライブラリに入れられる自作テンプレートは {n} 件までです。先に 1 つ削除してください。",
  "Billed by OpenAI in dollars, estimated from OpenAI's published prices (checked {date}).": "OpenAI からドルで請求されます。金額は OpenAI の公開価格（{date} 確認）からの見積もりです。",
  "Can't use that file": "このファイルは使えません",
  "It hasn't been read yet.": "まだ読み取られていません。",
  "It leaves this product's Library. The original stays in {product}.": "この商品のライブラリから外れます。元のテンプレートは {product} に残ります。",
  "It leaves this product's Library. You can add it again from the starters any time.": "この商品のライブラリから外れます。スターターからいつでも追加し直せます。",
  "No App Store reviews saved for this product yet. They're read with your App Store link.": "この商品の App Store レビューはまだ保存されていません。レビューは App Store のリンクから読み取られます。",
  "Prices from Higgsfield's cost check on {date}; the live price is checked again before it runs.": "価格は Higgsfield の {date} 時点の料金確認によるものです。実行前に最新の価格をもう一度確認します。",
  "Reading the image didn't finish. Try again.": "画像の読み取りが完了しませんでした。もう一度お試しください。",
  "Stands in for the ad's product: your product.": "広告内の商品の代わりになります：あなたの商品。",
  "Stands in for the ad's product: {slot}.": "広告内の商品の代わりになります：{slot}。",
  "Stats, reviews and ratings must be your own: real, sourced numbers (your user data or a published study) and a real customer's words, used with their permission. Made-up or rounded-up stats and invented reviews break Meta's ad policies and consumer-protection law.": "数値・レビュー・評価は、あなた自身のものに限ります。出典のある実際の数値（自社のユーザーデータや公表された研究）と、本人の許可を得た実際の顧客の言葉を使ってください。でっち上げや水増しの数値、架空のレビューは Meta の広告ポリシーと消費者保護法に違反します。",
  "That file isn't a PNG, JPEG or WebP image.": "このファイルは PNG・JPEG・WebP 画像ではありません。",
  "That style isn't in the Style Library.": "このスタイルはスタイルライブラリにありません。",
  "The prompt is {n} characters over Remix's limit; shorten the text.": "プロンプトがリミックスの上限を {n} 文字超えています。テキストを短くしてください。",
  "The request didn't go through. Check your connection and try again.": "リクエストを送信できませんでした。接続を確認して、もう一度お試しください。",
  "The server didn't answer. Try again.": "サーバーから応答がありませんでした。もう一度お試しください。",
  "The template library isn't in the database yet (migrations {first} and {second}).": "テンプレートライブラリがまだデータベースにありません（マイグレーション {first} と {second}）。",
  "The uploaded ad and its template are deleted from this product's storage (unless another product imported it). This can't be undone.": "アップロードした広告とそのテンプレートは、この商品のストレージから削除されます（ほかの商品がインポートしている場合を除く）。元に戻せません。",
  "The video isn't loaded yet. Try again in a moment.": "動画がまだ読み込まれていません。少し待ってからもう一度お試しください。",
  "This template can't be opened.": "このテンプレートは開けません。",
  "This template doesn't exist.": "このテンプレートは存在しません。",
  "This workspace doesn't exist.": "このワークスペースは存在しません。",
  "Upload an ad you like: it's read and turned into a clean, reusable template for this product. Or start from {n} proven formats. Templates stay with this product.": "気に入った広告をアップロードすると、読み取って、この商品で何度も使えるクリーンなテンプレートにします。実績のある {n} 種類のフォーマットから始めることもできます。テンプレートはこの商品専用です。",
  "{name} isn't a PNG, JPEG or WebP image.": "{name} は PNG・JPEG・WebP 画像ではありません。",
  "{n} characters: longer than this field's {max}, and a review can't be shortened and stay verbatim": "{n} 文字：この欄の上限 {max} 文字を超えています。レビューは短くすると原文のままではなくなります",
  "{n} proven Meta ad formats. Free to add; they stay in this product's Library.": "実績のある Meta 広告フォーマット {n} 種類。無料で追加でき、この商品のライブラリに残ります。",
