  "Starters are ready as they are.": "スターターはそのまま使えます。",
  "This product's Library is empty": "この商品のライブラリは空です",
  "Adds your brand's look, name and rules. Off: the prompt goes as written.": "ブランドのルック、名前、ルールを加えます。オフにするとプロンプトはそのまま送られます。",
  "Couldn't delete the result. Try again.": "結果を削除できませんでした。もう一度お試しください。",
