  "Couldn't start the upload: {message}": "アップロードを開始できませんでした：{message}",
  "Couldn't take a frame from the video.": "動画からフレームを取り出せませんでした。",
  "Couldn't upload the image. Try again.": "画像をアップロードできませんでした。もう一度お試しください。",
  "If the camera is a phone propped up, describe the camera position ('low static camera on the counter, looking up') rather than saying 'phone' — otherwise the model may also draw a phone in the scene.": "立てかけたスマホで撮るなら、「phone」と書かずにカメラの位置（例：「カウンターに置いた低い固定カメラで見上げる」）を書いてください。そうしないと、モデルが画面内にスマホまで描くことがあります。",
  "It's still being made: cancel its queued jobs first.": "まだ作成中です。先に待機中のジョブをキャンセルしてください。",
  "Made by OpenAI's Images API with this product's server key, billed by OpenAI in dollars (no Higgsfield credits). Estimated from OpenAI's published prices, checked {date}; reference images add an estimated input cost. Results are saved to this product's storage and checked like any other.": "この商品のサーバーキーで OpenAI の Images API を使って作成し、OpenAI からドルで請求されます（Higgsfield のクレジットは使いません）。料金は OpenAI の公開価格（{date} 確認）からの見積もりで、参考画像があると入力コストの見積もりが加わります。結果はこの商品のストレージに保存され、ほかと同じようにチェックされます。",
  "Pause on the frame you want: it's added to the form as an image": "使いたいフレームで一時停止すると、画像としてフォームに追加されます",
  "Prices from Higgsfield's cost check on {date}. Each job's live price is checked again before it runs, and one that costs much more is refused. Results are saved to this product's storage.": "価格は {date} の Higgsfield の料金チェックによるものです。各ジョブは実行前にもう一度最新価格を確認し、大幅に高いものは実行しません。結果はこの商品のストレージに保存されます。",
  "Product shots, app screens, a logo: they stand in for the reference's product and brand.": "商品写真、アプリ画面、ロゴ：参考画像の商品とブランドの代わりに使われます。",
  "That's the limit": "上限です",
  "The creative studio's tables aren't in the database yet (migration 20261002500000).": "クリエイティブ Studioのテーブルがまだデータベースにありません（マイグレーション 20261002500000）。",
  "The example is another brand's ad, used only for its layout. Its brand is replaced with yours and kept out of the result.": "見本はほかのブランドの広告で、レイアウトの参考にだけ使います。そのブランドはあなたのものに置き換えられ、結果には含まれません。",
  "The image is deleted from this product's storage and leaves Launch, where it's approved. This can't be undone.": "画像はこの商品のストレージから削除され、承認済みとして載っている「出稿」からも外れます。元に戻せません。",
  "The image is deleted from this product's storage. This can't be undone.": "画像はこの商品のストレージから削除されます。元に戻せません。",
  "The model's safety filter blocked this (often a false positive). Try: name a setting other than 'bathroom' (e.g. vanity sink, skincare routine), say the person is fully dressed, frame from the shoulders up, avoid words like 'dripping', 'leans over', 'body'.": "モデルのセーフティフィルターにブロックされました（誤判定のことがよくあります）。対策：「bathroom」以外の場所を指定する（例：洗面台、スキンケアの習慣）、人物がきちんと服を着ていると書く、肩から上で切り取る、「dripping」「leans over」「body」などの言葉を避ける。",
  "This generation doesn't exist.": "この生成は存在しません。",
  "This product doesn't exist.": "この商品は存在しません。",
  "This result doesn't exist.": "この結果は存在しません。",
  "What it's for": "向いている用途",
  "With only a start frame, the Higgsfield API makes the video in that image's shape (the aspect is used on the desktop runner).": "開始フレームだけの場合、Higgsfield API はその画像の形で動画を作ります（選んだ比率はデスクトップランナーで使われます）。",
  "With {n} images it runs on Higgsfield's API (the desktop runner sends at most {max}).": "画像が {n} 枚の場合は Higgsfield の API で実行します（デスクトップランナーが送れるのは最大 {max} 枚です）。",
  "Your text names {names}. Ads that name competitors are often rejected; it's kept as you wrote it.": "テキストに {names} の名前が入っています。競合の名前を出した広告は却下されることが多いですが、書いたとおりに残します。",
  "{provider}'s safety filter blocked this (sometimes a false positive). Rephrase the prompt (plainer wording, no real brands, people or claims it could read as harmful) or change the images.": "{provider} のセーフティフィルターにブロックされました（誤判定のこともあります）。プロンプトを書き直すか（平易な表現にし、実在のブランドや人物、有害と受け取られうる主張を入れない）、画像を変えてください。",
  "(voices, ambience)": "（声、環境音）",
  "1 reference": "参考画像 1 枚",
