  "Seedance 2.5 · {resolution} · {seconds} s · sound on": "Seedance 2.5 · {resolution} · {seconds} 秒 · 音声オン",
  "Seedance has no 4:5: the video is made in 3:4 (Meta trims it to 4:5).": "Seedance には 4:5 がないため、動画は 3:4 で作成されます（Meta が 4:5 にトリミングします）。",
  "Seedance makes 4:5 in 3:4 (Meta trims it to 4:5).": "Seedance は 4:5 を 3:4 で作成します（Meta が 4:5 にトリミングします）。",
  "Seedance takes a few minutes per clip. Credits are refunded when a generation is blocked.": "Seedance は 1 クリップに数分かかります。生成がブロックされた場合、クレジットは返金されます。",
  "Seedance takes a few minutes per clip.": "Seedance は 1 クリップに数分かかります。",
