  "The prompt is {n} character over the limit; shorten the text.": "プロンプトが上限を {n} 文字超えています。テキストを短くしてください。",
  "The prompt is {n} characters over the limit; shorten the text.": "プロンプトが上限を {n} 文字超えています。テキストを短くしてください。",
  "The prompt {provider} gets": "{provider} に送られるプロンプト",
  "The reference image has to be a public https link.": "参考画像は公開された https リンクである必要があります。",
  "The start frame has to be one of your images.": "開始フレームはあなたの画像のいずれかにしてください。",
  "The video opens on this image. Click to make it a plain reference.": "動画はこの画像から始まります。クリックすると通常の参考画像に戻します。",
  "Treat it as a list of changes to the reference instead": "参考画像への変更リストとして扱う",
