  "Create {n} creatives": "{n} 件のクリエイティブを作成",
  "Starting…": "開始中…",
  "Creatives can't be checked or approved until the AI is connected": "AI を接続するまで、クリエイティブのチェックも承認もできません",
  "UGC videos wait in the queue until the desktop runner is set up and running.": "UGC 動画は、デスクトップランナーが設定されて動き出すまでキューで待機します。",
  "AI videos wait in the queue until a Higgsfield key is added in Settings › Your keys.": "AI 動画は、「設定 › あなたのキー」で Higgsfield のキーを追加するまでキューで待機します。",
  "Images wait in the queue until a Higgsfield key is added in Settings › Your keys.": "画像は、「設定 › あなたのキー」で Higgsfield のキーを追加するまでキューで待機します。",
  "{kind} needs the desktop runner": "{kind}にはデスクトップランナーが必要です",
  "static": "静止画",
  "statics": "静止画",
  "videos": "動画",
  "The brief sums up what our top {kind} share.": "ブリーフには、成果トップの{kind}に共通する点をまとめています。",
  "The brief sums up what our top {kind} on {page} share.": "ブリーフには、{page} で成果トップの{kind}に共通する点をまとめています。",
  "The brief sums up what our top {n} {kind} share.": "ブリーフには、成果上位 {n} 件の{kind}に共通する点をまとめています。",
  "The brief sums up what our top {n} {kind} on {page} share.": "ブリーフには、{page} で成果上位 {n} 件の{kind}に共通する点をまとめています。",
  "{n} of their frames go along as style references.": "そのうち {n} 枚のフレームがスタイル参考として添付されます。",
  "{n} of their images go along as style references.": "そのうち {n} 枚の画像がスタイル参考として添付されます。",
  "None of their images could be sent, so the brief carries the structure alone.": "画像を送れなかったため、構成はブリーフだけで伝えます。",
  "Write a new hook: a clone of a live winner's line competes with it.": "新しいフックを書いてください。配信中の勝ち広告のセリフをそのまま使うと、その広告と競合します。",
  "More like our winners": "勝ち広告に似たものを",
  "Their offer wording:": "オファーの言い回し：",
  "{n} key frame of their video goes to Higgsfield as the shot and framing reference, then the images you picked and your screenshots.": "相手の動画のキーフレーム {n} 枚をショットと構図の参考として Higgsfield に送り、続いて選んだ画像とスクリーンショットを送ります。",
  "{n} key frames of their video go to Higgsfield as the shot and framing reference, then the images you picked and your screenshots.": "相手の動画のキーフレーム {n} 枚をショットと構図の参考として Higgsfield に送り、続いて選んだ画像とスクリーンショットを送ります。",
  "{n} key frame of their video goes to Higgsfield as the shot and framing reference, then your screenshots.": "相手の動画のキーフレーム {n} 枚をショットと構図の参考として Higgsfield に送り、続いてスクリーンショットを送ります。",
  "{n} key frames of their video go to Higgsfield as the shot and framing reference, then your screenshots.": "相手の動画のキーフレーム {n} 枚をショットと構図の参考として Higgsfield に送り、続いてスクリーンショットを送ります。",
  "Their image goes to Higgsfield as the layout and style reference, then the images you picked and your screenshots.": "相手の画像をレイアウトとスタイルの参考として Higgsfield に送り、続いて選んだ画像とスクリーンショットを送ります。",
  "Their image goes to Higgsfield as the layout and style reference, then your screenshots.": "相手の画像をレイアウトとスタイルの参考として Higgsfield に送り、続いてスクリーンショットを送ります。",
  "Their media isn't used; the images you picked and your brand screenshots are the references.": "相手のメディアは使いません。選んだ画像とブランドのスクリーンショットを参考にします。",
  "Their media isn't used; only your brand screenshots are references.": "相手のメディアは使いません。参考にするのはブランドのスクリーンショットだけです。",
  "Our logo goes to Higgsfield right after their image, labelled as ours.": "自社ロゴは相手の画像の直後に、自社のものとラベルを付けて Higgsfield に送られます。",
  "Our logo ({label}) goes to Higgsfield right after their image, labelled as ours.": "自社ロゴ（{label}）は相手の画像の直後に、自社のものとラベルを付けて Higgsfield に送られます。",
  "Our logo goes to Higgsfield right after their image, labelled as ours; the real file is then placed in the {where} of each finished image, inside Meta's safe area.": "自社ロゴは相手の画像の直後に、自社のものとラベルを付けて Higgsfield に送られます。その後、本物のファイルを完成した各画像の{where}、Meta のセーフエリア内に配置します。",
  "Our logo ({label}) goes to Higgsfield right after their image, labelled as ours; the real file is then placed in the {where} of each finished image, inside Meta's safe area.": "自社ロゴ（{label}）は相手の画像の直後に、自社のものとラベルを付けて Higgsfield に送られます。その後、本物のファイルを完成した各画像の{where}、Meta のセーフエリア内に配置します。",
  "Recreating {page}'s ad": "{page} の広告を再現中",
  "The brief copies its style, structure and pattern for {app}.": "ブリーフでは、そのスタイル・構成・パターンを {app} 向けに再現します。",
  "Exact: the brief edits their ad and is sent as written, with nothing of the Studio's own added.": "完全再現：ブリーフは相手の広告を編集するもので、Studio 独自の内容を加えずにそのまま送られます。",
  "Never in the creatives (checked in their on-screen text):": "クリエイティブに絶対に入れないもの（画面上のテキストでチェック）：",
  "Its kind, placement, variants, lengths and references are filled in below and under More options. Picking another start clears them.": "種類、配置、バリエーション、長さ、参考画像は下と「その他のオプション」に入力済みです。別の開始方法を選ぶとクリアされます。",
