  "AI video · Seedance 2.5 · made by Higgsfield": "AI 動画 · Seedance 2.5 · Higgsfield で作成",
  "A clip made from the brief, with the app's screenshots as references so the screens look like the real app. No presenter avatar; for a talking presenter use AI UGC video.": "ブリーフから作るクリップです。アプリのスクリーンショットを参考にするので、画面が実際のアプリらしく見えます。出演者アバターはありません。話す出演者が必要なら AI UGC 動画を使ってください。",
