  "Reference images · optional": "参考画像 · 任意",
  "Your product's own images for image ads and AI videos: they go to Higgsfield before the screenshots, and the scene is rebuilt around them, not pasted on.": "画像広告と AI 動画に使う自社商品の画像です。スクリーンショットより先に Higgsfield に送られ、貼り付けではなく、画像に合わせてシーンが作り直されます。",
  "The brief's OUR IMAGES line describes the images picked in Recreate: edit it to match your new picks.": "ブリーフの OUR IMAGES の行は、再現で選んだ画像を説明しています。新しく選んだ画像に合わせて編集してください。",
  "No logo yet: add your logo under App settings › Brand (kind Logo) or an app icon in the brand kit, and the real file is placed on every image instead of letting the model draw one.": "ロゴがまだありません。「アプリ設定 › ブランド」でロゴ（種類：ロゴ）を追加するか、ブランドキットにアプリアイコンを追加すると、モデルに描かせる代わりに本物のファイルがすべての画像に配置されます。",
  "Open App settings › Brand": "「アプリ設定 › ブランド」を開く",
  "Open App settings › Profile": "「アプリ設定 › プロフィール」を開く",
  "Our logo": "自社ロゴ",
  "Place the real logo": "本物のロゴを配置",
  "The exact file goes on every finished image, inside Meta's safe area (composed ads: in their layout's logo slot). The model is told not to draw a logo of its own, so no look-alike marks.": "完成した各画像に本物のファイルを、Meta のセーフエリア内に配置します（組版広告はレイアウトのロゴ枠に配置）。モデルには独自のロゴを描かないよう指示するので、似たマークは出ません。",
  "The exact file goes on every finished image, inside Meta's safe area. The model is told not to draw a logo of its own, so no look-alike marks.": "完成した各画像に本物のファイルを、Meta のセーフエリア内に配置します。モデルには独自のロゴを描かないよう指示するので、似たマークは出ません。",
  "Logo file": "ロゴファイル",
  "Composed ads: set the copy in your fonts": "組版広告：自社フォントでコピーを配置",
  "The model makes the scene and product with the copy zones empty; your words are then set on it exactly, at mobile-readable sizes, inside Meta's safe zones (4:5, 1:1 and 9:16 each laid out on its own). Editable afterwards for free, with an SVG and layers file.": "モデルがコピー部分を空けたままシーンと商品を作り、そこにあなたの言葉を正確に、スマホで読めるサイズで Meta のセーフゾーン内に配置します（4:5・1:1・9:16 はそれぞれ個別にレイアウト）。SVG とレイヤーファイル付きで、あとから無料で編集できます。",
  "No font files on the Brand page yet: they're set in Inter until you add them.": "ブランドページにフォントファイルがまだありません。追加するまでは Inter で配置されます。",
  "{used}/{max}. Short reads big: 3–7 words.": "{used}/{max}。短いほど大きく読めます：3〜7 語。",
  "One small habit. Every single day.": "小さな習慣を、毎日。",
  "Subhead · optional": "サブ見出し · 任意",
  "Eyebrow · optional": "アイブロウ · 任意",
  "Button · optional": "ボタン · 任意",
