  "Offer · optional": "オファー · 任意",
  "Only your own offers (Brand page).": "自社のオファーのみ（ブランドページ）。",
  "No offers on the Brand page: none can be shown.": "ブランドページにオファーがないため、表示できません。",
  "Add your offers on the Brand page first.": "先にブランドページでオファーを追加してください。",
  "No offer": "オファーなし",
  "Legal line · optional": "注意書き · 任意",
  "Results vary.": "効果には個人差があります。",
  "Clear it": "消去",
  "Clear them": "すべて消去",
  "Use the real product": "実物の商品を使う",
  "Your product's cut-out goes into the layout's product box with a soft floor shadow; the model leaves that spot empty, so labels are never misspelled or redrawn.": "商品の切り抜き画像を、やわらかな床の影を付けてレイアウトの商品枠に配置します。モデルはその場所を空けておくので、ラベルの誤字や描き直しは起きません。",
  "No cut-outs yet: under App settings › Brand, use “Make cut-out” on a product or packaging image.": "切り抜き画像がまだありません。「アプリ設定 › ブランド」で、商品やパッケージの画像に「切り抜きを作成」を使ってください。",
  "Tip: import your brand so the plate follows your look and the copy uses your fonts and offers.": "ヒント：ブランドをインポートすると、背景画像がブランドのルックに沿い、コピーにも自社のフォントとオファーが使われます。",
  "Import your brand": "ブランドをインポート",
  "No brand yet: fill it in under App settings and every prompt gets your look, voice, avatars and the only offers allowed.": "ブランドがまだありません。アプリ設定で入力すると、すべてのプロンプトにルック、トーン、ターゲット像、使ってよいオファーが入ります。",
  "Use the brand": "ブランドを使う",
  "The look opens every prompt, each variant speaks to the next avatar, and only your offers may appear (the check fails any other).": "ルックはすべてのプロンプトの冒頭に入り、各バリエーションは次のターゲット像に向けて話し、自社のオファーだけが使われます（それ以外はチェックで不合格）。",
  "See what's added": "追加内容を見る",
  "No AI product profile yet: add your website or App Store link under App settings › Profile and the prompts get who it's for, the promise, proof and your look.": "AI の商品プロフィールがまだありません。「アプリ設定 › プロフィール」でウェブサイトか App Store のリンクを追加すると、プロンプトに対象ユーザー、約束、根拠、ルックが入ります。",
  "Use the AI product profile": "AI の商品プロフィールを使う",
  "Every AI prompt gets who it's for and their pain, the promise, proof it may state, your look, and claims to avoid (checked too).": "すべての AI プロンプトに、対象ユーザーとその悩み、約束、言及できる根拠、ルック、避けるべき表現（チェックも行います）が入ります。",
  "Headline on top": "見出しを上に",
  "Headline beside the product": "見出しを商品の横に",
  "Offer badge": "オファーバッジ",
  "A big headline over the product, the CTA under it: the most common static ad.": "商品の上に大きな見出し、その下に CTA：最も一般的な静止画広告です。",
  "Copy on the left, the product on the right (stacked in 9:16): editorial, calm.": "左にコピー、右に商品（9:16 では縦に配置）：エディトリアルで落ち着いた印象。",
  "Headline, the product with one of your offers as a badge beside it, the CTA under it.": "見出し、横に自社オファーのバッジを付けた商品、その下に CTA。",
