  "The {layout} layout has no {roles}: they aren't on the ad. Pick a layout with them, or move the words into the subhead.": "「{layout}」レイアウトには{roles}がないため、広告に表示されません。それらがあるレイアウトを選ぶか、文言をサブ見出しに移してください。",
