  "The AI writes two versions of each: A in a creator's voice, B in the brand's, following your brand rules. Version A becomes the ad copy, and it is checked again.": "AI がブランドのルールに沿って、それぞれ 2 つのバージョンを作成します。A はクリエイターの口調、B はブランドの口調です。A が広告コピーになり、あらためてチェックされます。",
  "The check failed: fix the brief and make a new one. Failed creatives can't be approved.": "チェックに不合格でした。ブリーフを直して作り直してください。不合格のクリエイティブは承認できません。",
