  "No copy to read yet. Collect its ads again to get its text.": "まだ解析できるコピーがありません。テキストを取得するには広告を収集し直してください。",
  "No creatives stored yet": "保存済みのクリエイティブはまだありません",
  "No creatives stored": "保存済みのクリエイティブなし",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on Research.": "有料広告ならキーは不要です。広告ライブラリ拡張機能で競合の広告を収集し、リサーチでファイルをインポートしてください。",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on your app's Research page.": "有料広告ならキーは不要です。広告ライブラリ拡張機能で競合の広告を収集し、アプリのリサーチページでファイルをインポートしてください。",
  "No media to measure.": "計測できるメディアがありません。",
