  "Not enough room: {n} file ({size}) will be left behind.": "空き容量が足りません：{n} 件のファイル（{size}）は保存されません。",
  "Not enough room: {n} files ({size}) will be left behind.": "空き容量が足りません：{n} 件のファイル（{size}）は保存されません。",
  "Not read yet.": "まだ解析していません。",
  "Not read yet: new ads are read in the background, a few at a time.": "まだ解析していません。新しい広告はバックグラウンドで数件ずつ解析されます。",
  "Nothing to import": "インポートするものがありません",
  "Once the TypeSafe key is set, the AI reads each new ad for its format and hook, automatically, billed by TypeSafe.": "TypeSafe のキーを設定すると、AI が新しい広告ごとにフォーマットとフックを自動で解析します。料金は TypeSafe から請求されます。",
  "Once your OpenAI key is set, each new ad is read for its format and hook automatically:": "OpenAI のキーを設定すると、新しい広告ごとにフォーマットとフックが自動で解析されます：",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and each one's imported ads are filed under it.": "アプリ全体で 1 つの競合リストです。クリエイティブのチェックでこれらの名前が自社広告に入らないようにし、インポートした広告はそれぞれの競合の下に整理されます。",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and followed ones are included when you collect automatically.": "アプリ全体で 1 つの競合リストです。クリエイティブのチェックでこれらの名前が自社広告に入らないようにし、自動収集ではフォロー中の競合が対象になります。",
  "One per creative": "クリエイティブごとに 1 件",
  "Only the first {max} ads are imported, so no ads are marked as stopped.": "最初の {max} 件の広告だけをインポートするため、停止として扱われる広告はありません。",
  "Open ad from {name}": "{name} の広告を開く",
  "Open in Ad Library ↗": "広告ライブラリで開く ↗",
  "Open in TikTok ↗": "TikTok で開く ↗",
  "Open in the Meta Ad Library": "Meta 広告ライブラリで開く",
  "Open or Search": "開く／検索",
  "Open the brand's Facebook Page or its page in the Meta Ad Library and copy the link. Without one, its name is searched.": "ブランドの Facebook ページか、Meta 広告ライブラリのページを開いてリンクをコピーします。リンクがない場合は名前で検索します。",
  "Open your Facebook Page in the Ad Library, collect its ads with the Ad Library extension, then drop the file here and choose “Ours”.": "広告ライブラリで自社の Facebook ページを開き、広告ライブラリ拡張機能で広告を収集してから、ファイルをここにドロップして「自社」を選びます。",
  "Opens the Studio with a brief from what your top long-runners of a kind share (format, hook, proof, offer, CTA, layout), their images as style references and their offer wording. Every new ad still gets a new hook.": "同じ種類で長く配信されている上位広告の共通点（フォーマット、フック、根拠、オファー、CTA、レイアウト）、スタイル参考としての画像、オファーの言い回しをまとめたブリーフ付きで Studio を開きます。新しい広告にはそれぞれ新しいフックが付きます。",
  "Other advertisers": "その他の広告主",
