  "Pages": "ページ",
  "Paid ads your competitors are running now. The longer an ad runs and the more copies of it are live, the more likely it's working. Each new ad is read for its format, hook and structure on its own.": "競合がいま配信している有料広告です。長く配信され、配信中のコピーが多い広告ほど成果が出ている可能性が高いです。新しい広告はフォーマット、フック、構成が自動で解析されます。",
  "Partnership ad with {name}": "{name} とのパートナーシップ広告",
  "Partnership": "パートナーシップ",
  "Pick a competitor above the ads to see theirs in Meta's impressions order.": "広告の上で競合を選ぶと、その広告を Meta のインプレッション順で表示できます。",
  "Picked in a competitor analysis": "競合分析で選ばれた競合",
  "Platform": "プラットフォーム",
