  "Ran from": "出稿元",
  "Ranked #{rank} at {age}; an ad that age usually ranks about #{expected} ({curve}).": "配信 {age} の時点で #{rank}。同じ期間の広告は通常 #{expected} 前後です（{curve}）。",
  "Read from the ad copy. Scanning it in Recreate hears the video, and it's read again from what's said.": "広告コピーから解析しました。再現でスキャンすると動画の音声を聞き取り、話している内容からもう一度解析します。",
  "Read from what's said in the video, with the ad copy.": "動画で話している内容と広告コピーから解析しました。",
