  "Reading {n} new ad: format, hook and what each line does. They fill in as they're read.": "新しい広告 {n} 件を解析中：フォーマット、フック、各行の役割。解析が終わったものから表示されます。",
  "Reading {n} new ads: format, hook and what each line does. They fill in as they're read.": "新しい広告 {n} 件を解析中：フォーマット、フック、各行の役割。解析が終わったものから表示されます。",
