  "Saved {n} ad from {name} to Our ads: {created} new, {updated} updated.": "{name} の広告 {n} 件を「自社の広告」に保存しました：新規 {created} 件、更新 {updated} 件。",
  "Saved {n} ads from {name} to Competitors' ads: {created} new, {updated} updated.": "{name} の広告 {n} 件を「競合の広告」に保存しました：新規 {created} 件、更新 {updated} 件。",
  "Saved {n} ads from {name} to Our ads: {created} new, {updated} updated.": "{name} の広告 {n} 件を「自社の広告」に保存しました：新規 {created} 件、更新 {updated} 件。",
