  "Saving {n} image and video file to storage in the background ({stored} already saved).": "画像・動画ファイル {n} 件をバックグラウンドでストレージに保存しています（{stored} 件は保存済み）。",
  "Saving {n} image and video file to storage in the background.": "画像・動画ファイル {n} 件をバックグラウンドでストレージに保存しています。",
