  "Search the brand on library.tiktok.com with a European country picked, then paste the advertiser name it shows, or the link. TikTok lists ads shown in Europe only.": "library.tiktok.com でヨーロッパの国を選んでブランドを検索し、表示された広告主名かリンクを貼り付けます。TikTok はヨーロッパで表示された広告のみを掲載しています。",
