  "Suggested": "おすすめ",
  "That file isn't JSON. Pick a .json file the Ad Library extension saved.": "このファイルは JSON ではありません。広告ライブラリ拡張機能が保存した .json ファイルを選んでください。",
  "That isn't a file from the Ad Library extension. Drop the .json file it saved in Downloads/Ad Library, unchanged.": "これは広告ライブラリ拡張機能のファイルではありません。Downloads/Ad Library に保存された .json ファイルを、そのままドロップしてください。",
  "That's not an ads file: choose the .json files the Ad Library extension saved.": "広告ファイルではありません。広告ライブラリ拡張機能が保存した .json ファイルを選んでください。",
  "That's not an ads file: drop the .json files the Ad Library extension saved.": "広告ファイルではありません。広告ライブラリ拡張機能が保存した .json ファイルをドロップしてください。",
  "The AI then reads each new ad for its format and hook, automatically, billed by TypeSafe.": "その後、AI が新しい広告ごとにフォーマットとフックを自動で解析します。料金は TypeSafe から請求されます。",
  "The Ad Library extension": "広告ライブラリ拡張機能",
  "The ad couldn't be read.": "広告を解析できませんでした。",
  "The ads go up in parts of up to {n}: keep this tab open until the import finishes.": "広告は最大 {n} 件ずつに分けてアップロードされます。インポートが終わるまでこのタブを開いたままにしてください。",
  "The advertiser name in TikTok's Ad Library": "TikTok 広告ライブラリでの広告主名",
  "The collection stopped early, so no ads are marked as stopped.": "収集が途中で止まったため、停止として扱われる広告はありません。",
  "The collectors couldn't be checked just now. Importing files works as usual; reload to check again.": "いまは収集ツールを確認できませんでした。ファイルのインポートは通常どおり使えます。再読み込みするともう一度確認します。",
  "The file has no ads. Check the Ad Library page and collect again.": "ファイルに広告がありません。広告ライブラリのページを確認して、もう一度収集してください。",
  "The images and videos are deleted from storage. The ads stay in the list and fall back to their Ad Library links, which stop working after a few days. Collect the ads again and import the file to save them again.": "画像と動画はストレージから削除されます。広告はリストに残り、広告ライブラリのリンクに戻りますが、そのリンクは数日で使えなくなります。もう一度保存するには、広告を収集し直してファイルをインポートしてください。",
  "The import stopped": "インポートが止まりました",
  "The order under Meta's \"total impressions\" sort when the ads were collected; ranks compare within one advertiser": "広告を収集した時点の Meta「合計インプレッション」順。順位は同じ広告主の中で比較します",
  "Their ads, copy and posters still are. Freeing space doesn't change this per-file limit; it's your Supabase project's upload limit (Storage settings).": "広告、コピー、ポスター画像は保存されます。空き容量を増やしてもこのファイルごとの上限は変わりません。これは Supabase プロジェクトのアップロード上限です（Storage の設定）。",
  "Their images and videos are saved to storage in the background so they don't expire.": "画像と動画は期限切れにならないよう、バックグラウンドでストレージに保存されます。",
  "Their images and videos couldn't be queued for storage: {error}": "画像と動画をストレージ保存の待ち行列に追加できませんでした：{error}",
  "There's no setting to turn this off.": "この機能をオフにする設定はありません。",
  "This import stores {n} file ({size}).": "このインポートでは {n} 件のファイル（{size}）を保存します。",
  "This import stores {n} file ({size}); {stored} are already stored and are skipped.": "このインポートでは {n} 件のファイル（{size}）を保存します。保存済みの {stored} 件はスキップします。",
  "This import stores {n} files ({size}).": "このインポートでは {n} 件のファイル（{size}）を保存します。",
  "This import stores {n} files ({size}); {stored} are already stored and are skipped.": "このインポートでは {n} 件のファイル（{size}）を保存します。保存済みの {stored} 件はスキップします。",
