  "{n} file ({size}) is over the {limit} upload limit and won't be stored.": "{n} 件のファイル（{size}）はアップロード上限 {limit} を超えているため保存されません。",
  "{n} file couldn't be saved. Either its link expired before it was saved (collect the advertiser's ads again and import the file), or it's a video over the storage upload limit, which isn't stored (its ad and poster are).": "{n} 件のファイルを保存できませんでした。保存前にリンクが期限切れになったか（広告主の広告を収集し直してファイルをインポートしてください）、ストレージのアップロード上限を超える動画で保存対象外です（広告とポスター画像は保存されます）。",
  "{n} file didn't report a size, so it's estimated.": "{n} 件のファイルはサイズが不明なため、推定値で計算しています。",
  "{n} file stored ({size}) — kept until you delete them": "{n} 件のファイルを保存済み（{size}）— 削除するまで保持されます",
  "{n} files ({size}) are over the {limit} upload limit and won't be stored.": "{n} 件のファイル（{size}）はアップロード上限 {limit} を超えているため保存されません。",
  "{n} files couldn't be saved. Either their link expired before they were saved (collect the advertiser's ads again and import the file), or they're videos over the storage upload limit, which aren't stored (their ads and posters are).": "{n} 件のファイルを保存できませんでした。保存前にリンクが期限切れになったか（広告主の広告を収集し直してファイルをインポートしてください）、ストレージのアップロード上限を超える動画で保存対象外です（広告とポスター画像は保存されます）。",
