  "(none on the Product page or the Brand page)": "（商品ページにもブランドページにもありません）",
  "A bright kitchen in the morning": "朝の明るいキッチン",
  "A clip made with Seedance 2.5 (on the Higgsfield API, or the desktop runner when the API isn't set up); no presenter avatar. It can follow their key frames.": "Seedance 2.5 で作るクリップです（Higgsfield API、API 未設定ならデスクトップランナー）。出演者アバターはなし。相手のキーフレームに沿わせられます。",
  "A comparison of the app against the old way, with ticks and crosses. Never names a competitor.": "アプリと従来のやり方を ○× で比較します。競合の名前は出しません。",
  "A credible presenter answers the question buyers keep asking, then points to the tool.": "信頼感のある出演者が、買い手がよく抱く疑問に答え、ツールへとつなげます。",
  "A diary-style run through a day where the product shows up naturally at the moment it matters.": "日記風に 1 日を追い、ここぞという場面で商品が自然に登場します。",
  "A different person": "別の人物",
  "A first-person story told as it unfolds, turning into the lesson the product solves.": "一人称で語る進行中のストーリーが、商品で解決できる教訓へとつながります。",
  "A link of theirs would send your clicks to them.": "相手のリンクだと、あなたのクリックが相手に流れます。",
  "A man in his 20s, casual look": "20 代の男性、カジュアルな雰囲気",
  "A person talks to camera through most of it, so it's remade as an AI UGC video with a presenter.": "ほぼ全編で人物がカメラに向かって話しているため、出演者ありの AI UGC 動画として作り直します。",
  "A presenter in front of an app screen or a fact card, explaining it.": "アプリ画面やファクトカードの前で出演者が説明します。",
  "A presenter talking to camera, made with Marketing Studio on the desktop runner.": "カメラに向かって話す出演者を、デスクトップランナー上の Marketing Studio で作ります。",
  "A presenter talks to camera in a casual style about the problem and the app as the fix (a presenter, never a customer).": "出演者がカジュアルにカメラへ語りかけ、悩みと解決策としてのアプリを紹介します（あくまで出演者で、顧客ではありません）。",
  "A real address that isn't yours.": "あなたのものではない実在のアドレスです。",
  "A real number that isn't yours.": "あなたのものではない実在の番号です。",
  "A real person's name or likeness; never reuse it.": "実在の人物の名前や肖像です。絶対に使い回さないでください。",
  "A real place that isn't yours.": "あなたのものではない実在の場所です。",
  "A real-feeling user talks to camera about the problem and how the product fixed it.": "リアルなユーザーがカメラに向かって、悩みと商品でどう解決したかを語ります。",
  "A short acted scene of a situation the buyer knows too well, with the product as the punchline.": "買い手がよく知るシチュエーションを短い寸劇にし、商品をオチにします。",
  "A shot-by-shot prompt for a video tool (Higgsfield's Seedance, Sora, Veo). Generate here makes stills only; for a video, send it to Studio.": "動画ツール（Higgsfield の Seedance、Sora、Veo）向けのショットごとのプロンプトです。「ここで生成」は静止画のみ。動画は Studio に送ってください。",
  "A still image in its style": "その雰囲気の静止画",
  "A video prompt": "動画用プロンプト",
  "A way to make it yours:": "自社向けにするアイデア：",
  "A woman in her 30s, casual, at her kitchen table": "30 代の女性、カジュアルな服装で、キッチンのテーブルに座っている",
  "AI / actor UGC": "AI／俳優 UGC",
  "AI advice; you decide": "AI の助言です。判断はあなたに",
  "About {n} s": "約 {n} 秒",
  "Add an image key to generate here": "画像用のキーを追加すると、ここで生成できます",
  "Add images": "画像を追加",
  "Add or sort images in App settings › Brand": "「アプリ設定 › ブランド」で画像を追加・並べ替え",
