  "An aspirational message over cinematic footage, tying the product to the life the buyer wants.": "映画のような映像に憧れを誘うメッセージを重ね、商品を買い手が望む暮らしに結びつけます。",
  "An avatar, or describe one. A different person from theirs.": "アバターを選ぶか、人物を記述してください。相手とは別の人物にします。",
