  "Confirm {rules} in docs/POLICY.md before this runs.": "実行前に docs/POLICY.md で {rules} を確認してください。",
  "Copy breakdown": "分解内容をコピー",
  "Copy script": "スクリプトをコピー",
  "Copy structure": "コピーの構成",
  "Copy text": "テキストをコピー",
  "Copy the format, never the asset. Their footage, script, voice and likeness stay theirs: reusing them invites copyright and IP reports, and Meta acts on those by rejecting ads and can restrict the ad account. These prompts keep only the structure, hook pattern and pacing, rewritten for your app, with an original presenter who never poses as a customer or an expert.": "真似るのはフォーマットだけで、素材そのものは使いません。相手の映像、台本、声、肖像は相手のものです。流用すると著作権や知的財産の申し立てを招き、Meta は広告を不承認にしたり、広告アカウントを制限したりすることがあります。これらのプロンプトは構成、フックのパターン、テンポだけを残してあなたのアプリ向けに書き直し、顧客や専門家を装わないオリジナルの出演者を使います。",
  "Copy this static": "この静止画広告をコピー",
