  "Phone number": "電話番号",
  "Pick up to {max}; none are picked for you.": "最大 {max} 枚まで選べます。自動では選ばれません。",
  "Pick {name}": "{name} を選択",
  "Picked images go to Higgsfield after their ad; the scene is rebuilt around them, not pasted on.": "選んだ画像は相手の広告の後に Higgsfield へ送られます。画像を貼り付けるのではなく、それを中心にシーンを組み立て直します。",
  "Picked images go to Higgsfield as references; the scene is rebuilt around them, not pasted on.": "選んだ画像は参考画像として Higgsfield へ送られます。画像を貼り付けるのではなく、それを中心にシーンを組み立て直します。",
  "Place our logo on the finished image": "完成画像に自社ロゴを配置",
  "Policy check passed": "ポリシーチェック合格",
  "Post copy": "投稿文",
  "Prefilled from your Brand. Every field overrides their ad.": "ブランドから入力済みです。各項目は相手の広告より優先されます。",
  "Prefilled with their text; yours now.": "相手のテキストを入力済みです。ここからはあなたの言葉に。",
  "Prefilled with their words: rewrite them in yours.": "相手の文言を入力済みです。自分の言葉で書き直してください。",
  "Price or offer": "価格・オファー",
  "Price, offer or code": "価格、オファー、コード",
  "Product demo": "商品デモ",
  "Promise a count, then deliver each item fast with a number on screen.": "数を予告し、画面に番号を出しながら各項目をテンポよく紹介します。",
  "Promise a count, then deliver it in order.": "数を予告し、順番に紹介します。",
  "Promise one outcome, then walk through it in clear numbered steps on screen.": "1 つの成果を約束し、画面上で番号付きのわかりやすいステップで説明します。",
  "Prompt for": "プロンプトの用途",
  "Put the old way next to the better way and let the difference show.": "従来のやり方とより良いやり方を並べ、違いを見せます。",
  "Queue it": "キューに追加",
  "Queued {n} job for about {credits} credits.": "{n} 件のジョブをキューに追加しました（約 {credits} クレジット）。",
  "Queued {n} jobs for about {credits} credits.": "{n} 件のジョブをキューに追加しました（約 {credits} クレジット）。",
  "Quiz / result reveal": "診断／結果発表",
  "React to a relatable prompt (a question, a headline you write yourself), then answer it with the product.": "共感できるお題（質問や自作の見出し）にリアクションし、商品で答えます。",
  "Reaction": "リアクション",
  "Read it again": "もう一度解析",
  "Read the ad (the link at the top) to list what changes: their name and wordmark, product, claims and every line of text.": "広告を読み取って（上部のリンク）、変更点を一覧にします：相手の名前とワードマーク、商品、主張、すべての文言。",
  "Read the ad again to check whether it fits what you sell (advice only).": "広告をもう一度読み取ると、自社の商品に合うか確認できます（助言のみ）。",
  "Read the ad to check whether it fits what you sell (advice only).": "広告を読み取ると、自社の商品に合うか確認できます（助言のみ）。",
  "Read the ad": "広告を読み取る",
  "Read the whole video": "動画全体を読み取る",
  "Read {date} (the poster frame only)": "{date} に読み取り（ポスターフレームのみ）",
  "Read {date}": "{date} に読み取り",
  "Reading it again needs {keys}": "もう一度読み取るには {keys} が必要です",
  "Reading the video and its audio…": "動画と音声を読み取り中…",
  "Reading their ad for what to swap…": "差し替える要素を探すため、相手の広告を読み取り中…",
  "Reading their ad needs {keys}": "相手の広告を読み取るには {keys} が必要です",
  "Reading their ad…": "相手の広告を読み取り中…",
  "Reading their video to tell a presenter-to-camera ad from an animated or demo one…": "相手の動画を読み取り、出演者がカメラに語る広告か、アニメーションやデモかを判別中…",
  "Ready-made prompt": "用意済みのプロンプト",
  "Real review quotes and ratings carry the ad. Only real, consented reviews.": "実際のレビューの引用と評価で広告を構成します。本物で、同意を得たレビューのみ。",
  "Rebuild from the fields": "入力項目から作り直す",
  "Rebuild it from the fields": "入力項目から作り直す",
  "Recreate for {app}": "{app} 用に再現",
