  "Words on their image": "相手の画像内の文字",
  "Write a replacement that isn't their text, or remove it.": "相手の文言ではない置き換えを書くか、削除してください。",
  "Write the prompt": "プロンプトを書いてください",
  "Written from everything above. Edit it if you like.": "上の内容すべてから作成しました。必要なら編集してください。",
  "You edited the prompt by hand, so changes above don't reach it.": "プロンプトを手動で編集したため、上の変更は反映されません。",
  "You edited the prompt, so it doesn't describe these images yet: rebuild it from the fields.": "プロンプトを編集したため、まだこれらの画像の説明が入っていません。入力項目から作り直してください。",
  "You edited the prompt: changes to the fields don't reach it until you rebuild it.": "プロンプトを編集済みです。作り直すまで、入力項目の変更は反映されません。",
  "Your Brand's app icon": "ブランドのアプリアイコン",
  "Your brand has no {items} yet, so the prompt uses plainer wording. You can still continue.": "ブランドに{items}がまだないため、プロンプトはシンプルな表現になります。このまま続けられます。",
