  "{name} is busy right now (too many requests). Wait a minute and retry, or switch provider.": "{name} は現在混み合っています（リクエストが多すぎます）。1 分ほど待って再試行するか、プロバイダーを切り替えてください。",
  "{name} refused the prompt under its content rules. Edit the prompt (fewer claims, no people or brands) and retry.": "{name} がコンテンツルールによりプロンプトを拒否しました。プロンプトを編集して（主張を減らし、人物やブランドを入れない）再試行してください。",
  "{name} says the account is out of credits or over its limit. Top it up on {name}'s site, then retry, or switch provider.": "{name} によると、アカウントのクレジットが不足しているか上限を超えています。{name} のサイトでチャージしてから再試行するか、プロバイダーを切り替えてください。",
  "{name} took too long for this Supabase plan. Retry with a lower quality or resolution.": "{name} の処理がこの Supabase プランの上限時間を超えました。品質か解像度を下げて再試行してください。",
