  "Click a row to see its ads. Stopped counts start from your imports: an ad launched and stopped between two imports is never seen.": "行をクリックするとその広告を表示します。停止数はインポートを起点に数えるため、2回のインポートの間に配信開始・停止した広告は記録されません。",
  "Collect ads for every followed competitor": "フォロー中のすべての競合の広告を収集",
  "Collect each advertiser once a day at most and spread runs out. Past 20 runs in a day the extension asks you to confirm.": "各広告主の収集は1日1回までにし、実行の間隔をあけてください。1日に20回を超えると、拡張機能が確認を求めます。",
