  "Meta blocked a run ({page}) in the last 6 hours. Cooldown until {time}.": "直近6時間に Meta が実行（{page}）をブロックしました。クールダウンは {time} までです。",
  "Meta blocked a run in the last 6 hours. Cooldown until {time}.": "直近6時間に Meta が実行をブロックしました。クールダウンは {time} までです。",
  "Meta doesn't share spend or conversions for these ads outside the EU; long runs, many variants and Meta's impressions order are the best signals of what's working.": "EU 以外では、Meta はこれらの広告の消化金額やコンバージョンを公開していません。配信期間の長さ、バリエーションの多さ、Meta のインプレッション順が、効いている広告を見極める最良の手がかりです。",
  "Meta shows 3 or more ads using this creative": "このクリエイティブを使った広告が Meta 上に3件以上あります",
