  "No Page saved: searches the Ad Library for “{terms}”. Add its Page link under Add or edit to open its own page.": "ページが保存されていないため、広告ライブラリで「{terms}」を検索します。「追加・編集」でページのリンクを追加すると、そのページを直接開けます。",
  "No ads came in.": "広告は取り込まれませんでした。",
