  "Our ads live 45+ days, oldest first: likely wearing out, so make the next version before they stop": "45日以上配信中の自社広告を古い順に。効果が落ちてきている可能性が高いので、止まる前に次のバージョンを用意しましょう",
  "Our ads live {n}+ days: likely wearing out, so make the next version before they stop": "{n} 日以上配信中の自社広告。効果が落ちてきている可能性が高いので、止まる前に次のバージョンを用意しましょう",
  "POV skit": "POV コント",
  "Paid-ads research isn't set up in the database yet (migration 20261002300000_paid_ads).": "有料広告のリサーチがまだデータベースに設定されていません（migration 20261002300000_paid_ads）。",
  "Parallel or back-to-back sessions from one connection are a common reason Meta blocks it for hours.": "同じ接続からの並行・連続したセッションは、Meta に数時間ブロックされるよくある原因です。",
  "Partnership ads (run with a creator's or another Page) live 30+ days": "30日以上配信中のパートナーシップ広告（クリエイターや他のページと共同で配信）",
