  "Paste the Page's link (facebook.com/…), its Ad Library link, or its numeric Page id.": "ページのリンク（facebook.com/…）、広告ライブラリのリンク、または数字のページ ID を貼り付けてください。",
  "Paste the advertiser's name as TikTok's Ad Library shows it, or a library.tiktok.com link with its business id.": "TikTok の広告ライブラリに表示される広告主名、またはビジネス ID を含む library.tiktok.com のリンクを貼り付けてください。",
  "Paste the competitor's website (like notion.so) or its advertiser link from adstransparency.google.com.": "競合のウェブサイト（例：notion.so）、または adstransparency.google.com の広告主リンクを貼り付けてください。",
  "Proven winners": "実証済みの勝ちパターン",
