  "Share of live ads that are video": "配信中の広告のうち、動画の割合",
  "Share still running, of the ads first seen here {n}+ days ago ({name} only): a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "ここで {n} 日以上前に初めて確認した広告のうち、まだ配信中の割合（{name} のみ）。割合が高いほど、広告主がその種類の広告にお金を払い続けていることを意味します。10件未満のグループは除外。インポートするたびに精度が上がります。",
  "Share still running, of the ads first seen here {n}+ days ago: a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "ここで {n} 日以上前に初めて確認した広告のうち、まだ配信中の割合。割合が高いほど、広告主がその種類の広告にお金を払い続けていることを意味します。10件未満のグループは除外。インポートするたびに精度が上がります。",
  "Show all the text": "テキストをすべて表示",
  "Show {name}'s ads": "{name} の広告を表示",
  "Silent text": "無音テキスト",
  "Started in the last 7 days": "直近7日以内に開始",
  "Static benefit image": "ベネフィットを伝える静止画",
  "Still live and started 30+ days ago: an advertiser that keeps paying for an ad is telling you it works": "30日以上前に開始して今も配信中。広告主がお金を払い続けているのは、その広告が効いている証拠です",
  "Stopped after 30+ days": "30日以上配信後に停止",
