  "Stopped · 14d": "停止 · 14日",
  "Switched off: {sources}. Turn them on in {link}.": "オフ：{sources}。{link} でオンにできます。",
  "That Transparency Center link has no advertiser in it. Open the advertiser's page and copy its link (it has AR… in it).": "この透明性センターのリンクには広告主が含まれていません。広告主のページを開いてリンクをコピーしてください（AR… を含むリンクです）。",
  "That doesn't look like a Facebook Page id or facebook.com link.": "Facebook のページ ID や facebook.com のリンクではないようです。",
