  "That upload is over 10 MB. Reload the page (a current Research page sends a big file in parts) and import it again.": "アップロードが 10 MB を超えています。ページを再読み込みして（最新のリサーチページは大きなファイルを分割して送ります）、もう一度インポートしてください。",
  "The .json files the Ad Library extension saves: one per Page, as many as you like at once.": "広告ライブラリ拡張機能が保存する .json ファイル。ページごとに1つで、一度に何個でも追加できます。",
  "The .json files the Ad Library extension saves: one per competitor, as many as you like at once.": "広告ライブラリ拡張機能が保存する .json ファイル。競合ごとに1つで、一度に何個でも追加できます。",
  "The Ad Library link expired before this file was saved": "このファイルを保存する前に、広告ライブラリのリンクの期限が切れました",
  "The earlier versions couldn't be loaded.": "以前のバージョンを読み込めませんでした。",
  "The extension collects one competitor at a time, at least 30 minutes apart, and stops for 6 hours if Meta shows a block sign. It runs in its own small window: keep part of it visible while you work elsewhere.": "拡張機能は競合を1社ずつ、30分以上の間隔をあけて収集し、Meta がブロックの兆候を示すと6時間停止します。専用の小さなウィンドウで動くので、別の作業中もその一部が見えるようにしておいてください。",
  "The extension stopped and started a 6-hour cooldown. Visiting the Ad Library again from the same connection before it ends can stretch the block.": "拡張機能は停止し、6時間のクールダウンに入りました。終了前に同じ接続から広告ライブラリにアクセスすると、ブロックが長引くことがあります。",
  "The median across competitors: each competitor counts once": "競合全体の中央値（各競合を1回ずつ数えます）",
  "The research backend isn't deployed yet.": "リサーチのバックエンドはまだデプロイされていません。",
