  "To refresh one: click {open}, click “Collect ads” in the Ad Library extension, then drop the saved file above. Click a name to see its ads.": "更新するには、「{open}」をクリックし、広告ライブラリ拡張機能で「広告を集める」をクリックしてから、保存されたファイルを上にドロップします。名前をクリックするとその広告を表示します。",
