  "Up to {n} ads for at most {usd}, billed per ad by Apify from your Apify credit. Most collections stop well below the limit: a brand with 30 live ads costs for 30.": "最大 {n} 件の広告、上限 {usd}。Apify が広告1件ごとに Apify クレジットから請求します。たいていは上限よりずっと安く済みます。配信中の広告が30件のブランドなら、30件分です。",
