  "Start in the middle of a story: “Last [time], I [moment that went wrong]…”": "物語の途中から始めます：「[いつ]、私は [うまくいかなかった瞬間]…」",
  "Start the analysis": "分析を開始",
  "Start the run": "実行を開始",
  "Starting the scrapers": "収集ツールを起動中",
  "Starts from your app's profile": "アプリのプロフィールから開始",
  "Starts from your app's profile: finds your competitors and what wins for them on each channel.": "アプリのプロフィールから始めます：競合と、各チャネルで当たっている要素を見つけます。",
  "State your strongest claim flatly, no warm-up: “[Result] without [the usual pain].”": "前置きなしで一番強い主張を言い切ります：「[いつもの悩み] なしで [結果]」。",
  "Step 2 of 3": "ステップ 2／3",
  "Stop": "停止",
  "Stop the competitor search?": "競合の検索を停止しますか？",
  "Stop the run": "実行を停止",
  "Stop the search": "検索を停止",
  "Stop this run?": "この実行を停止しますか？",
  "Stopping…": "停止中…",
  "Story": "ストーリー",
  "Tagged": "タグ付け",
  "Tagging friends": "友だちをタグ付け",
  "Tags @{handle}": "@{handle} をタグ付け",
  "Talking to camera": "カメラに語りかけ",
  "Tease the answer and hold it back: “Nobody tells you this about [topic]…”": "答えをほのめかして引っ張ります：「[テーマ] について誰も教えてくれないこと…」",
  "Tell them exactly what to do next (comment a word, tap the link, save it).": "次に何をすればいいかをはっきり伝えます（ひと言コメント、リンクをタップ、保存する）。",
  "Text on screen": "画面上のテキスト",
  "The AI names the brands you're up against with their social accounts, checks each one against your app, and you pick who to study.": "AI が競合ブランドとその SNS アカウントを挙げ、1 つずつあなたのアプリと照合します。調べる相手はあなたが選びます。",
  "The account": "アカウント",
  "The analysis, all its runs and their reports are deleted for good.": "この分析、すべての実行、そのレポートが完全に削除されます。",
  "The app reads the brand's tagged posts and collab posts, then checks creators' bios for ties like “athlete @brand”, “ambassador” or a discount code. Posts from those creators count even when they don't tag the brand. Adds about $1.40.": "ブランドがタグ付けされた投稿やコラボ投稿を読み取り、クリエイターのプロフィールに「athlete @brand」「ambassador」や割引コードなどのつながりがないか確認します。そうしたクリエイターの投稿は、ブランドをタグ付けしていなくても対象になります。約 $1.40 追加されます。",
  "The best came from {account}.": "ベストは {account} の投稿です。",
  "The creators who delivered for this brand, ranked.": "このブランドで成果を出したクリエイターのランキング。",
  "The demo analysis can't collect new posts.": "デモの分析では新しい投稿を収集できません。",
  "The hook": "フック",
  "The last run stopped": "前回の実行が止まりました",
  "The list below is replaced by a fresh search. Competitors you added yourself are kept only if they're on your product profile.": "下のリストは新しい検索結果に置き換わります。自分で追加した競合は、商品のプロフィールにある場合のみ残ります。",
  "The pains they recognise": "共感される悩み",
  "The server didn't answer. Check your connection and reload the page.": "サーバーから応答がありません。接続を確認してページを再読み込みしてください。",
  "The strongest format on {channel} is “{format}” (typical {views} views over {posts} posts).": "{channel} で最も強いフォーマットは「{format}」です（{posts} 件の投稿で標準再生数 {views}）。",
  "The top hook on {channel}, from {account} · {views} views.": "{channel} のトップフック（{account}・再生数 {views}）。",
  "The top posts around these terms from any creator, ranked by buyers in the comments, not just views. If no competitors turn up, this runs on its own.": "これらのキーワードに関する、あらゆるクリエイターの上位投稿。再生数だけでなく、コメント内の購入者で順位付けします。競合が見つからなくても、これ単独で実行されます。",
  "Them: “{text}”": "相手：「{text}」",
  "This analysis doesn't exist": "この分析は存在しません",
  "This run has no report.": "この実行にはレポートがありません。",
  "This run is still going.": "この実行はまだ進行中です。",
  "Time frame": "期間",
  "Try the analysis again": "分析をもう一度試す",
  "Turn on “Read more comments” and run it again: up to 25 comments are read on each channel's most-viewed posts and sorted into what buyers want, ask and doubt.": "「コメントをさらに読む」をオンにして再実行してください。各チャネルで再生数の多い投稿のコメントを最大 25 件読み、購入者が求めていること・質問・疑問に分類します。",
  "Typical views": "標準再生数",
  "Unrelated": "無関係",
  "Up to 25 comments on each channel's 20 most-viewed posts, to find buyers and what your audience asks for. Adds about $1–4 per run.": "各チャネルで再生数上位 20 件の投稿から、それぞれ最大 25 件のコメントを読み、購入者やオーディエンスが求めていることを見つけます。1 回の実行につき約 $1〜4 追加されます。",
  "Up to 25 comments on each channel's 20 most-viewed posts, to spot buyers and what the audience asks for.": "各チャネルで再生数上位 20 件の投稿から、それぞれ最大 25 件のコメントを読み、購入者やオーディエンスが求めていることを見つけます。",
  "Views/day": "1 日あたり再生数",
  "Wait for the current step to finish, or stop it first.": "現在のステップが終わるまで待つか、先に停止してください。",
  "Wait for the current step to finish.": "現在のステップが終わるまでお待ちください。",
  "Waiting for the first update…": "最初の更新を待っています…",
  "Walk through the steps, one per beat.": "ステップを 1 パートに 1 つずつ見せます。",
