  "Click {open} on a competitor above (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "上の競合で「{open}」をクリックし（新しいタブで広告ライブラリが開きます）、拡張機能のオレンジのアイコンから「{collect}」をクリックします。",
  "Click {open} on one of your Pages above (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "上の自社ページのいずれかで「{open}」をクリックし（新しいタブで広告ライブラリが開きます）、拡張機能のオレンジのアイコンから「{collect}」をクリックします。",
  "Add your Facebook Page above, then click {open} on it (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "上で自社の Facebook ページを追加して「{open}」をクリックし（新しいタブで広告ライブラリが開きます）、拡張機能のオレンジのアイコンから「{collect}」をクリックします。",
  "Add a competitor above, then click {open} on it (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "上で競合を追加して「{open}」をクリックし（新しいタブで広告ライブラリが開きます）、拡張機能のオレンジのアイコンから「{collect}」をクリックします。",
  "For their organic posts, see {link}.": "オーガニック投稿は{link}をご覧ください。",
  "Install it once: {guide} shows each click, from unzipping to pinning it in Chrome.": "最初に一度インストールします。{guide}で、解凍から Chrome への固定まで、すべての操作を説明しています。",
  "the step-by-step guide": "ステップごとのガイド",
  "Pause following": "フォローを一時停止",
  "This can't be undone: to follow it again, add it and collect its ads again. To keep its data and only stop updating it, use Pause following instead.": "元に戻せません。もう一度追うには、追加し直して広告を収集してください。データを残して更新だけ止めたい場合は、代わりに「フォローを一時停止」を使います。",
  "{free} the Chrome extension saves a competitor's Meta ads as a file you drop on this page (steps under “How to get ads in”).": "{free}Chrome 拡張機能が競合の Meta 広告をファイルに保存するので、それをこのページにドロップします（手順は「広告のインポート方法」にあります）。",
  "Want it quicker? {make} gives a ready-made prompt, one image here, or a Studio batch.": "もっと手早く作りたいなら、{make}で用意済みのプロンプト、ここで画像 1 枚、または Studio でのまとめて作成が使えます。",
  "Seedance follows their shots and framing ({level}, set by Closeness) while every brand detail becomes yours; their video file itself is never sent.": "Seedance は相手のショットと構図をなぞり（{level}、「近さ」で設定）、ブランドの要素はすべてあなたのものに置き換えます。相手の動画ファイル自体は送信されません。",
  "Use {n} key frame of their video as Higgsfield's reference (at {times}).": "相手の動画のキーフレーム {n} 枚（{times} 時点）を Higgsfield の参考画像にします。",
  "Use {n} key frames of their video as Higgsfield's reference (at {times}).": "相手の動画のキーフレーム {n} 枚（{times} 時点）を Higgsfield の参考画像にします。",
  "No AI product profile yet: add your website or App Store link on the {link} so the prompt knows who you sell to, your promise and your proof.": "AI 商品プロフィールがまだありません。{link}でウェブサイトか App Store のリンクを追加すると、プロンプトに販売先、約束、裏付けが反映されます。",
  "Profile tab of App settings": "「アプリ設定」の「プロフィール」タブ",
  "The finished file is still at {provider}: {link} (the link may expire).": "完成ファイルはまだ {provider} にあります：{link}（リンクは期限切れになる場合があります）。",
