  "A clip made with Seedance 2.5 on the Higgsfield API; no presenter avatar. It can follow their key frames.": "Higgsfield API の Seedance 2.5 で作るクリップで、出演者のアバターはありません。相手のキーフレームに沿って作れます。",
  "Their ads, copy and posters still are. Freeing space doesn't change this per-file limit; it comes with your plan.": "相手の広告、コピー、ポスター画像は保存されます。容量を空けてもこの 1 ファイルあたりの上限は変わりません。上限はプランで決まります。",
  "Optional. Most people don't need this: add a Google Drive folder to share finished creatives there.": "任意です。ほとんどの方には不要です。Google Drive のフォルダーを追加すると、完成したクリエイティブをそこで共有できます。",
  "Optional. Most people never need these.": "任意です。ほとんどの方には必要ありません。",
