  "The owner can't delete their account here. Give the workspace to someone else first, or delete the whole workspace (its Supabase project).": "オーナーはここで自分のアカウントを削除できません。先にワークスペースを別の人に引き継ぐか、ワークスペース全体（その Supabase プロジェクト）を削除してください。",
  "Accounts can't be deleted in this workspace. Ask whoever runs it.": "このワークスペースではアカウントを削除できません。管理者にお問い合わせください。",
